(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["ar"] = {"ui":{"lead":"لم يكتفِ الناس بلعب الألعاب، بل رسموها أيضًا. كبّر لوحات وتماثيل تمتد على 3300 سنة وتأمّل تفاصيلها.","details":"تفاصيل","links":"شاهد اللعبة أو العبها","record":"عن العمل","game":"لعبة","exhibit":"المقتنيات","room":"قاعة","room_chance":"الحظ","hint":"اقرص أو استخدم العجلة للتكبير · اسحب للتحريك · المس رقمًا","r_artist":"الفنان","r_date":"التاريخ","r_place":"المكان","r_medium":"المادة والتقنية","r_size":"المقاس","r_museum":"المتحف","r_credit":"مصدر الاقتناء","r_rights":"الصورة","met":"متحف المتروبوليتان للفنون","cc0":"وصول مفتوح (ملك عام)","metlink":"صفحة العمل على موقع المتحف","credit":"الصور: متحف المتروبوليتان للفنون ومتحف كليفلاند للفنون ومعهد شيكاغو للفنون ومتحف ريكس، وصول مفتوح (ملك عام).","cma":"متحف كليفلاند للفنون","aic":"معهد شيكاغو للفنون","rijks":"متحف ريكس، أمستردام"},"nefertari":{"title":"الملكة نفرتاري تلعب السنت","artist":"نينا دي غاريس ديفيز (نسخة)","date":"الأصل نحو 1290–1224 ق.م · النسخة 1921–22","place":"مصر (وادي الملكات)","game":"السنت","medium":"تمبرا على ورق (نسخة بنصف الحجم)","p":["كانت نفرتاري الزوجة الملكية الكبرى لرمسيس الثاني. هذه نسخة من رسم في مقبرتها بوادي الملكات، صُنعت داخل المقبرة نفسها في 1921–22، ونُقلت حتى الشقوق والأجزاء المفقودة من الجدار.","تجلس الملكة أمام رقعة وتلعب السنت مع خصم غير مرئي. ويُرجَّح أن اللعبة المرسومة في مقبرة كانت تعني أكثر من التسلية: الفوز في رحلة العالم الآخر."],"spots":[["نوعان من القطع","على الرقعة قطع مدبّبة الرأس وقطع على شكل بكرة: مجموعة لكل لاعب."],["يد الملكة","أصابعها تمتد إلى قطعة."],["الرقعة والحامل","رُسمت الرقعة من الجانب فلا تظهر خاناتها، وهي على حامل رفيع الأرجل."],["اسمها","اسم الملكة مكتوب داخل إطار بيضاوي يسمّى الخرطوش."],["الخصم الخفي","لا أحد أمامها: إنها تلعب مع خصم لا يُرى."]]},"hydria":{"title":"أخيل وأياكس يلعبان لعبة رقعة (جرّة ماء)","artist":"يُنسب إلى مجموعة لياغروس","date":"نحو 510 ق.م","place":"اليونان (أتيكا)","game":"لعبة نرد","medium":"فخار (أسلوب الأشكال السوداء)","p":["في أثناء حصار طروادة يقضي بطلان يونانيان، أخيل وأياكس، الوقت حول رقعة. ابتكر هذا المشهد نحو 540 ق.م الخزّاف والرسام إكسيكياس، وأصله محفوظ على أمفورا في متاحف الفاتيكان.","لقي الموضوع رواجًا كبيرًا بين نحو 540 و480 ق.م، ويُعرف منه أكثر من 150 مثالًا. وفي هذه الجرّة تقف الإلهة أثينا في الوسط. يلعب البطلان لعبة تتحرك فيها القطع بحسب رمية النرد."],"spots":[["أثينا","تقف الإلهة أثينا بين الاثنين."],["البطل الأيسر","ما زال الرمح في يده وهو ينحني على الرقعة."],["البطل الأيمن","لم يضع سلاحه هو الآخر: لحظة لعب في قلب الحرب."],["الرقعة","الكتلة المنخفضة بينهما هي الرقعة."],["الكتف","على كتف الجرّة عربة تنطلق."]]},"liubo":{"title":"تمثالان جالسان يلعبان ليوبو","date":"القرن الأول ق.م – القرن الأول م","place":"الصين (أسرة هان)","game":"ليوبو","medium":"فخار ملوّن","p":["لاعبان لليوبو، اللعبة التي شغفت بها صين أسرة هان. كانت مثل هذه التماثيل توضع في القبور أملًا في أن تستمر متع الحياة بعد الموت.","في الصورة وُضعت بينهما رقعة ليوبو وقطع العظم من مقتنيات هذا المتحف. ويلتقط التمثالان لحظة مثيرة من مباراة حامية."],"spots":[["رقعة ليوبو","هي نفسها «رقعة ليوبو وقطعها» في المقتنيات: لاحظ علامات T وL وV."],["اللاعب الأيسر","يتأمل الرقعة بهدوء."],["اللاعب الأيمن","يده مرفوعة وفمه مفتوح: هل قام للتوّ بالحركة الحاسمة؟"],["قطع على الرقعة","قطع العظم قائمة عند طرفي الرقعة."],["قطع خارج الرقعة","وهناك قطع أخرى على الأرض."]]},"shahnama":{"title":"«بزرجمهر يحلّ لغز لعبة الشطرنج الهندية»، من شاهنامه الشاه طهماسب","artist":"يُنسب الرسم إلى عبد الوهاب","date":"نحو 1530–35","place":"إيران (تبريز)","game":"الشطرنج","medium":"ألوان مائية معتمة وحبر وفضة وذهب على ورق","p":["مشهد من ملحمة الفردوسي «الشاهنامه» (كتاب الملوك). يرسل ملك الهند رسولًا معه رقعة شطرنج وقطعها، ويتحدى ملك الفرس أنوشروان: إن عرف كيف تُلعب دفعت الهند الجزية.","لم يحلّها في الوقت المحدد إلا الحكيم الشاب بزرجمهر. وفي الشاهنامه ترسل فارس النرد في المقابل، فيعجز الهنود عن حلّه. يحدّق الملك وحاشيته في الرقعة واللاعبين."],"spots":[["رقعة الشطرنج","القطع على رقعة مربعات، صغيرة جدًا حتى يصعب تمييز أشكالها."],["الملك أنوشروان","على عرشه ينتظر حلّ اللغز."],["حول الرقعة","اللاعبون منحنون على الرقعة."],["الأبيات","في الإطارين العلوي والسفلي أبيات من الفردوسي."],["الحاشية","رجال بعمائم ذات عصيّ حمراء طويلة يتفرجون وقوفًا."]]},"chaupar":{"title":"شيفا وبارفاتي يلعبان التشاوبار، من سلسلة «راسامانجاري»","artist":"ديفيداسا من نوربور","date":"1694–95","place":"الهند (باسوهلي، جامو)","game":"التشاوبار (قريب لسلف لعبة لودو)","medium":"ألوان مائية معتمة وحبر وفضة وذهب على ورق","p":["صفحة من سلسلة توضّح «راسامانجاري»، قصيدة حب سنسكريتية من القرن الخامس عشر. يجلس الإله شيفا وزوجته بارفاتي على جلد نمر حول رقعة صليبية الشكل.","لقد انتزع شيفا للتوّ عقد بارفاتي بالغش، وهي تتوسل إليه. ألوان جريئة، وعمق مكاني مبهم، ولون وإيماءة يحملان معنى: هذه سمات مدرسة باسوهلي."],"spots":[["الرقعة الصليبية","تُلعب التشاوبار والباتشيسي على رقعة بهذا الشكل الصليبي."],["أعواد بيضاء على الرقعة","على الأرجح نرد التشاوبار الطويل (باسا)."],["شيفا","أبيض الجسد، وحول عنقه أفعى."],["بارفاتي","تمدّ يدها وتطلب عقدها."],["جلد النمر","يجلسان على جلد نمر."]]},"shogi":{"title":"شابة وشاب يلعبان الشوغي («تشوناغون كانيسوكي»، من الشعراء الخالدين الستة والثلاثين)","artist":"سوزوكي هارونوبو","date":"نحو 1767–69","place":"اليابان (إدو)","game":"الشوغي","medium":"طباعة خشبية ملوّنة (نيشيكي-إي)","p":["مطبوعة من سلسلة تلمّح إلى الشعراء الخالدين الستة والثلاثين، وهذه ترمز إلى الشاعر تشوناغون كانيسوكي. في ليلة صيف، بجانب ناموسية، تجلس شابة وشاب أمام رقعة شوغي.","هارونوبو هو الفنان الذي نشر المطبوعات الكاملة الألوان المطبوعة بألواح كثيرة. حتى القطع على الرقعة مرسومة بدقة."],"spots":[["رقعة شوغي بأرجل","رقعة سميكة بأرجل، كما هي اليوم."],["علبة صغيرة","على الأرجح علبة القطع."],["الناموسية","ناموسية خضراء معلّقة: إنها ليلة صيف."],["الفانوس","مصباح قائم يضيء الرقعة."],["القصيدة","في الإطار السحابي اسم الشاعر وقصيدة."]]},"sugoroku":{"title":"شابتان تلعبان السوغوروكو","artist":"أوتاغاوا تويوكوني الأول","date":"عصر إدو (أواخر القرن الثامن عشر – أوائل التاسع عشر)","place":"اليابان (إدو)","game":"بان-سوغوروكو (قريب النرد)","medium":"ثنائية من المطبوعات الخشبية","p":["مطبوعتان تتصلان في صورة عريضة: شابات مجتمعات في غرفة يستمتعن بلعب بان-سوغوروكو. هذه اللعبة قريبة النرد، ومن سلالة رقعة سوغوروكو شوسوئين في هذه المقتنيات.","على الرقعة حجارة بيضاء وسوداء، والشابة على اليمين تمسك كوبًا لهزّ النرد. ومن النافذة يظهر جبل فوجي."],"spots":[["الرقعة","حجارة بيضاء وسوداء على خاناتها الطويلة."],["كوب النرد","يُهزّ فيه النرد."],["حجارة خارج الرقعة","أُخرجت بالفعل، أم لم تدخل بعد؟"],["جبل فوجي","فوجي خلف النافذة."],["موضع الالتقاء","هنا تلتقي المطبوعتان."]]},"eakins":{"title":"لاعبو الشطرنج","artist":"توماس إيكنز","date":"1876","place":"الولايات المتحدة (فيلادلفيا)","game":"الشطرنج","medium":"زيت على خشب","p":["في صالون بيت في فيلادلفيا يلعب صديقان الشطرنج بينما يتفرج والد الفنان، بنجامين إيكنز. تعلّم إيكنز بناء المكان بعناية والتفاصيل الدقيقة من أستاذه في باريس، جيروم.","في عام 1881 صارت «لاعبو الشطرنج» أول عمل يقبله متحف المتروبوليتان هديةً من فنان على قيد الحياة."],"spots":[["قطع الشطرنج","في الغرفة المعتمة تبرز قطع الرقعة في الضوء."],["والد الفنان","واقفًا يتابع المباراة: بنجامين إيكنز."],["اللاعب الأيمن","الرسام جورج و. هولمز، صديق والد الفنان."],["الدرج","نقش لاتيني: «رسم هذا ابن بنجامين إيكنز في عام ٧٦»."],["فوق المدفأة","نسخة من لوحة لجيروم، أستاذ إيكنز."],["القطة","على الأرض، تبدو القطة وحدها غير مهتمة بالمباراة."]]},"weiqi":{"title":"طبق عليه خالدون يلعبون الويتشي","artist":"مجهول","date":"1425–1436 (أسرة مينغ، عهد شيوان-ده)","place":"الصين","game":"الغو (الويتشي)","medium":"ورنيش (لاكيه) محفور أحمر وأخضر","size":"ارتفاع 3.5، عرض 14.9، طول 23.5 سم","credit":"هدية فلورنس وهربرت إرفينغ، 2015","p":["طبق من الورنيش المحفور: طُليت عشرات الطبقات ثم حُفرت، وتحت الطبقة الحمراء طبقة خضراء، فيُظهر عمق الحفر الألوان. وداخل الحافة المفصّصة يلعب خالدون الغو تحت شجرة صنوبر.","في الصين أسطورة «لانكه» أي «مقبض الفأس المتعفّن»: شاهد الحطّاب وانغ تشي خالدين يلعبون الغو في الجبل، ولمّا انتبه وجد أن زمنًا طويلًا مضى حتى تعفّن مقبض فأسه. وكان الخالدون أمام اللوحة موضوعًا محبّبًا. ولا تذكر السجلات من يكون الشخص الواقف."],"spots":[["اللوحة","لوحة الغو بين الخالدَين، محفورة حتى خطوطها."],["الخالدان يلعبان","شخصان جالسان قرب الصخور حول اللوحة."],["الشخص الواقف","شخص يقف بعيدًا قليلًا. يذكّر بالحطّاب في الأسطورة، لكن لا يُعرف من هو."],["القمر","قمر مستدير في السماء (أو لعلها الشمس)."],["الصنوبر","صنوبرة باسطة أغصانها، شجرة كثيرًا ما ترمز إلى طول العمر وأرض الخالدين."],["حافة الفاوانيا","حُفرت على الحافة أزهار فاوانيا كبيرة وأوراقها."]]},"webb":{"title":"لاعبا الطاولة (خزانة)","artist":"فيليب ويب (تصميم)، إدوارد بيرن-جونز (رسم)، موريس ومارشال وفوكنر وشركاه (صنع)","date":"1861","place":"بريطانيا (لندن)","game":"الطاولة (النرد)","medium":"خشب صنوبر ملوّن، ألوان زيتية على جلد، نحاس أصفر، نحاس","size":"ارتفاع 185.4، عرض 114.3، عمق 53.3 سم","credit":"صندوق روجرز، 1926","p":["من أوائل قطع الأثاث في الشركة التي أسّسها ويليام موريس مع أصدقائه سنة 1861. على جلد البابين رُسم بالزيت رجل وامرأة بثياب العصور الوسطى يلعبان الطاولة. وعُرضت الخزانة في معرض لندن الدولي سنة 1862.","وهي تلخّص هدف حركة الفنون والحِرف في محو الحدّ بين الفنون الجميلة والفنون التطبيقية. أما خلفية الجلد فمدقوقة بنقاط دقيقة، على طريقة العصور الوسطى."],"spots":[["اللوحة","لوحة الطاولة على المنضدة بينهما."],["الرجل","شاب يمسك قطعة ويتأمل اللوحة."],["المرأة","امرأة تجلس قبالته وتمسك قطعة (أو كوب النرد)."],["الزهور عند القدمين","تتفتح الزهور عند أقدام اللاعبَين."],["الجلد المدقوق","خلفية الجلد مدقوقة بنقاط دقيقة تلتقط الضوء."],["أشرطة المعيّنات","أشرطة من المعيّنات على أرضية ذهبية تؤطّر البابين من أعلى وأسفل."]]},"liberale":{"title":"لاعبو الشطرنج","artist":"ليبيرالي دا فيرونا","date":"نحو 1475","place":"إيطاليا (فيرونا)","game":"الشطرنج","medium":"تمبرا على خشب","size":"34.9 × 41.3 سم","credit":"مجموعة ميتلاند ف. غريغز، وصية ميتلاند ف. غريغز، 1943","p":["هذه قطعة من واجهة «كاسوني»، الصندوق المزخرف الذي كانت العروس تحفظ فيه جهازها في إيطاليا عصر النهضة. وقد عُرف ليبيرالي أيضًا بتزيين كتب الترانيم في كاتدرائية سيينا.","وتعرض اللوحة لحظة من قصة حب غير معروفة الاسم. ففي القطعة الرفيقة تبدو فتاة عند نافذة كأنها تدعو شابًا إلى الدخول، وهنا يلعب الاثنان الشطرنج. وبحسب المتحف فهي على وشك الخسارة. وكان الشطرنج صورة محببة للتودد في أدب الحب في ذلك العصر."],"spots":[["رقعة الشطرنج","رقعة حمراء وبيضاء عليها قطع داكنة، ويبدو الدور قريبًا من نهايته."],["الشاب","يمد يده نحو الرقعة، ويبدو أنه سيفوز."],["الفتاة","تجلس قبالته، وفي القطعة الرفيقة تدعوه من النافذة."],["النافذة","خلف النافذة المفتوحة تلّ وسماء."],["شبان يتفرجون","رجال عاقدو الأذرع يتابعون الدور."],["فتيات يتفرجن","فتيات يختلسن النظر إلى الدور من وراء العمود."]]},"mirror":{"title":"غطاء مرآة: زوجان يلعبان الشطرنج","artist":"مجهول","date":"1325–1350","place":"فرنسا (باريس)","game":"الشطرنج","medium":"عاج","size":"القطر 10.2 سم","credit":"اشتُري من صندوق ج. هـ. ويد، 1940","p":["كان هذا القرص العاجي الذي في حجم الكف غطاءً لمرآة يد. ففي باريس القرن الرابع عشر كانت المرآة المعدنية المصقولة تُحفظ بين لوحين من العاج وتُحمل باليد، وكانت منحوتات العاج هذه من الكماليات التي أحبها أهل البلاط والنبلاء.","داخل خيمة مرفوعة الستائر يلعب شاب وسيدة الشطرنج. وفي قصص العصور الوسطى كان الشطرنج رمزًا للحب والحرب معًا. وقد قيل إن الاثنين هما تريستان وإيزولده أو لانسلوت وغوينيفير، لكن لا أحد يعرف. ويسأل المتحف زواره: من تظن أنه يفوز؟"],"spots":[["رقعة الشطرنج","رقعة على طاولة بساق واحدة، عليها بضع قطع."],["الشاب","يمد يده ليلعب نقلته التالية."],["السيدة","امرأة بغطاء رأس، تلمس أطراف أصابعها قطعة على الرقعة."],["اليد المقبوضة","يدها الأخرى مقبوضة في حجرها. أتراها تمسك قطعة أسرتها؟"],["الخيمة","ستائر معقودة على الجانبين، وهي خلفية مألوفة لمشاهد الشطرنج على أغطية المرايا."]]},"morris":{"title":"لوح لعب (لعبة الطاحونة)","artist":"بيتر فلوتنر","date":"1500–1546","place":"ألمانيا","game":"لعبة الطاحونة (ناين منز موريس)","medium":"حفر على الخشب","credit":"صندوق تشارلز و. هاركنس الوقفي، 1923","p":["طبعة خشبية لبيتر فلوتنر، أحد أمهر النحاتين في نورنبرغ عصر النهضة، وقد صمم أيضًا الزخارف والأثاث ونماذج الصاغة ومجموعة ورق لعب اشتهرت بسخريتها. وتحت الأغصان الملتفة يختبئ لوح لعبة الطاحونة («موله» بالألمانية): ثلاثة مربعات متداخلة متصلة عند منتصف كل ضلع.","في اللوح 24 نقطة. ومن صفّ ثلاثًا من قطعه في خط (طاحونة) أخذ قطعة من خصمه. وكانت هذه الطبعات نماذج للحرفيين أيضًا، وقد عرض المتحف هذه الورقة في معرض لنماذج الصاغة وتصاميمهم. ولا يُعرف أكانوا يلعبون على الورق نفسه أم ينقلونه إلى الخشب أو المعدن."],"spots":[["المربع الأوسط","المربع الداخلي، مملوء بتشابك دقيق."],["زاوية خارجية","زاوية المربع الخارجي، وهي إحدى النقاط الأربع والعشرين التي توضع عليها القطع."],["زاوية وسطى","زوايا المربع الأوسط نقاط أيضًا."],["خطوط الوصل","أشرطة تصل المربعات الثلاثة عند منتصف الأضلاع، وتتحرك عليها القطع أيضًا."],["قناع","أطر ملتفة ووجوه في الأعلى والأسفل والجانبين، من زخرفة الغروتسك في عصر النهضة."],["إطار الكرمة","أوراق وثمار محفورة بالأبيض على أرضية سوداء."]]},"leifeng":{"title":"لوح لعبة باغودا لايفنغ","artist":"مجهول","date":"1736–1795 (عهد تشيان لونغ)","place":"الصين","game":"لعبة سباق","medium":"طبعة خشبية؛ حبر على ورق","size":"31 × 29.8 سم","credit":"اشتُري من صندوق ج. هـ. ويد، 2025","p":["ورقة مطبوعة صُنعت للعب، من عهد الإمبراطور تشيان لونغ في صين أسرة تشينغ. وفي خاناتها شخصيات «أسطورة الأفعى البيضاء»: روح الأفعى باي سوجن («السيدة البيضاء»)، ورفيقتها شياو تشينغ («الخضراء الصغيرة»)، والشاب شو شوان (شو شيان في الروايات اللاحقة)، والراهب فاهاي الذي يسجن السيدة البيضاء في النهاية تحت باغودا لايفنغ على ضفة البحيرة الغربية.","يلتف المسار حلزونيًا من خانة كُتب عليها 起馬، أي «انطلق»، إلى الباغودا في الوسط. ولعل اللاعبين تسابقوا عبر القصة بالنرد كما في لعبة الإوزة الغربية، ولم تُحفظ القواعد. وبحسب المتحف كانت هذه المطبوعات الملونة تُباع في المدن وتُعلّق على الجدران جزءًا من الثقافة البصرية الحضرية، وكل لون يُطبع بلوح محفور خاص به."],"spots":[["البداية","الخانة المكتوب عليها 起馬، أي «انطلق»، وهي على الأرجح نقطة البداية."],["السيدة البيضاء والخضراء الصغيرة","روح الأفعى باي سوجن ورفيقتها شياو تشينغ."],["شو شوان","الشاب الذي يتزوج السيدة البيضاء."],["الراهب فاهاي","الراهب الذي يسجنها تحت الباغودا."],["باغودا لايفنغ","الباغودا على البحيرة الغربية في هانغتشو، حيث تنتهي القصة."],["الوسط","امرأة جالسة أمام الباغودا ورجل جاثٍ، المشهد الأخير من القصة، ولعله خط النهاية."]]},"tutinama":{"title":"القرد الجريح يعضّ يد الأمير رفيقه في الشطرنج (من «طوطي نامه»، حكايات الببغاء)","artist":"داساوانتا","date":"نحو 1560","place":"الهند (بلاط أكبر المغولي)","game":"الشطرنج","medium":"ألوان صمغية وحبر وذهب على ورق","size":"20 × 14.2 سم (الصورة 10.2 × 10.6 سم)","credit":"هدية السيدة أ. دين بيري، 1962","p":["صورة من «طوطي نامه» أي «حكايات الببغاء»، صُنعت في بلاط الإمبراطور المغولي أكبر. وهي إحدى الحكايات التي ترويها أم الببغاوات لصغارها لتحذّرهم من مصادقة أنواع أخرى من المخلوقات، مثل صغار الثعالب. وفيها قرد بارع في الشطرنج كان يلاعب أميرًا كثيرًا.","وذات يوم، أمام الضيوف، أطلق القرد مزحة فظة فصفعه الأمير، فعضّ القرد يد الأمير. وفي الخارج إلى اليمين يعدّ الخدم الطعام والضيوف ينظرون مذهولين. ويذكر نقش في الأسفل اسم داساوانتا الذي صار لاحقًا من أشهر أساتذة البلاط المغولي، وقد وضع وهو شاب طبقة من الأزرق البارد تحت صورته."],"spots":[["القرد","يعضّ يد الأمير رفيقه في الشطرنج."],["الأمير","الأمير الذي عُضّت يده."],["رقعة الشطرنج","رقعة بمربعات حمراء على الأرض."],["الضيوف المذهولون","الضيوف المدعوون إلى المجلس."],["إعداد الطعام","في الخارج يضع الخدم القدور على النار."],["النص الفارسي","في الأعلى كُتبت الحكاية بالفارسية."]]},"teniers":{"title":"دور في النرد (الطاولة)","artist":"دافيد تينيرز","date":"أربعينيات القرن السابع عشر","place":"الفلاندر","game":"الطاولة (الباكغامون)","medium":"زيت على خشب، نُقل إلى قماش","size":"59 × 80.6 سم","credit":"هدية السيد والسيدة صموئيل د. وايز، 1943","p":["دور في الطاولة على رهان كبير رسمه الفلمنكي تينيرز. واللعبة قديمة جدًا: ظهرت صورتها الحديثة في القرن الخامس عشر، ووُلد اسم «باكغامون» نحو زمن هذه اللوحة. وكانت في القرن السابع عشر شائعة جدًا، وكثيرًا ما لُعبت على المال.","يحيط المتفرجون باللاعبين، وعند الجدار رجل يسجّل النقاط. ومن النساء اللواتي يتفرجن — وإحداهن تطل من نافذة — يرى المتحف أن الغرفة قاعة قمار في ماخور. وكثيرًا ما حملت مشاهد اللعب هذه موعظة: القمار حماقة، بل شر، ومضيعة للوقت."],"spots":[["اللوح","لوح طاولة مفتوح على المنضدة، والدور جارٍ."],["الرجل ذو القميص الأبيض","لاعب يُدير ظهره ويمد يده إلى قطعه."],["الرجل المتأمل","خصمه، يسند خده إلى يده."],["مسجّل النقاط","رجل يعلّم لوحًا على الجدار: النقاط أم الرهان؟"],["المرأة في النافذة","امرأة مسنّة تنظر من الأعلى."],["الغرفة الخلفية","في الخلف يشرب رجال قرب امرأة شابة."]]},"imari":{"title":"طبق عليه رجلان يلعبان الغو","artist":"مجهول","date":"القرن الثامن عشر","place":"اليابان (عصر إدو)","game":"الغو","medium":"خزف مصبوب بألوان فوق الطلاء الزجاجي (هيزن، طراز إيماري)","size":"2.4 × 13.8 سم","credit":"مجموعة سيفيرانس وغريتا ميليكين، 1964","p":["على هذا الطبق المربع الصغير يلعب رجلان الغو تحت شجرة صنوبر: صاحب الثوب الأصفر يجلس قبالة اللوح الموضوع على الأرض مباشرة، وخصمه ذو الثوب الأخضر يستند إلى الشجرة.","إنه خزف إيماري من هيزن (ساغا وناغاساكي اليوم)، وتذكّر خضرته بألوان كوتاني. وقد صُنع للتصدير، حين حلّت اليابان محل الصين موردًا رئيسيًا للخزف إلى أوروبا."],"spots":[["لوح الغو","لوح مخطط موضوع على الأرض مباشرة."],["صاحب الثوب الأصفر","يجلس قبالة اللوح."],["صاحب الثوب الأخضر","خصمه، يستند إلى الشجرة مبتسمًا."],["الصنوبر","صنوبرة تمد أغصانها فوقهما."],["الإطار الأحمر","إطار أحمر مقطوع الزوايا يحيط بالمشهد."]]},"shoei":{"title":"الفنون الأربعة (أحد زوج من الستائر)","artist":"يُنسب إلى كانو شوئي","date":"أواخر القرن السادس عشر–أوائل السابع عشر","place":"اليابان (عصر موموياما)","game":"الغو","medium":"أحد زوج من الستائر ذات الألواح الستة؛ حبر وألوان خفيفة على ورق","size":"153 × 358.6 سم","credit":"صندوق جون ل. سيفيرانس، 1979","p":["ستارة قابلة للطي من ستة ألواح تُنسب إلى كانو شوئي من مدرسة كانو. وهي مع قرينتها تصوّر «الفنون الأربعة» المنتظرة من الرجل الصيني المثقف: العزف على آلة التشين، ولعب التشي (الغو)، والخط، والرسم. وهنا يستريح سادة صينيون من علية القوم مع خدمهم في الريف تحت أشجار الصنوبر.","في الوسط يلعب رجلان الغو ويتفرج ثالث. وعلى طاولة قريبة كتب وآلة تشين ما زالت في غلافها القماشي تنتظر من يعزف عليها. والمشهد يوازن بين المتعة والوقار. ويلفت المتحف إلى أن أحد الخدم شغلته حركة سمكة في الماء."],"spots":[["لوح الغو","لوح بقوائم يلعب عليه سيدان متقابلان."],["السادة","لاعبان وثالث يتفرج."],["الطاولة","على الأرجح الطاولة التي عليها الكتب والتشين في غلافه."],["الخدم","خدم ينتظرون قرب الطاولة."],["الخادم الشارد","مستلقٍ عند الماء يراقب سمكة."],["الصنوبرة","صنوبرة كبيرة تمد أغصانها فوق المشهد."]]},"umaya":{"title":"ستارة الإسطبل (الغو والشوغي على الشرفة)","artist":"مجهول","date":"أوائل القرن السادس عشر","place":"اليابان (عصر موروماتشي)","game":"الغو والشوغي","medium":"واحدة من زوج من الستائر القابلة للطي ذات الألواح الستة؛ حبر وألوان وذهب على ورق","size":"146.1 × 346.6 سم","credit":"صندوق إدوارد ل. ويتمور، 1934","p":["هذه الستارة المؤلفة من ستة ألواح متصلة واحدة من زوج. قد تكون الخيول الثمينة في حظائرها هي الموضوع الأساسي، لكن الكثير يجري على الشرفة في المقدمة.","هناك يتبارى الناس في لعبتين مختلفتين: الغو على اليسار والشوغي على اليمين. ويرى المتحف أن حيوية المشهد تنبع من التقابل بين الخيول القلقة والاستراتيجية الهادئة للعبتين. وفي اليابان كان يُعتقد أن القردة تحمي الخيول، فكانت تُربّى أحيانًا في الإسطبلات."],"spots":[["رقعة الغو","رقعة دقيقة الخطوط عليها أحجار سوداء."],["رجلان بقلنسوتين سوداوين","رجال يعتمرون قلنسوة الإيبوشي السوداء العالية: صاحب الثوب الأخضر يمد يده إلى الرقعة، وصاحب الأحمر يتفرّج."],["رقعة الشوغي","رقعة خاناتها كبيرة — أقل بكثير من رقعة الغو."],["الخصم الضاحك","راهب حليق الرأس يلتقط قطعة، والرجل المقابل يمسك رأسه ويقهقه. هل سجّل أحدهما نقطة للتو؟"],["قرد","في طرف الشرفة — قرد يرتدي سترة حمراء؟"],["حصان","حصان أسود يرفع قائمتيه الأماميتين، مشدود بالحبال."]]},"goryeo":{"title":"إبريق سيلادون مطعّم بشخصين يلعبان الغو","artist":"مجهول","date":"القرن الثالث عشر","place":"كوريا (سلالة غوريو)","game":"الغو (بادوك)","medium":"سيلادون مطعّم بطين سائل أبيض وأسود","size":"الارتفاع 20.4 سم، القطر 14.3 سم","credit":"هدية جون ل. سيفيرانس، 1917","p":["إبريق من سيلادون غوريو له صنبور ومقبض. كان التطعيم — حفر الخطوط في الطين وملؤها بطين سائل أبيض وأسود ثم التزجيج والحرق — من براعات خزّافي غوريو؛ وهنا يبرز بالأبيض داخل إطار مستدير شخصان جالسان تحت شجرة صفصاف.","بينهما رقعة، ويقارن المتحف المشهد بصور لعب الغو (البادوك بالكورية). كان العزف والغو والخط والرسم «الفنون الأربعة» للعالِم المثقف، وصارت مجالسهم الأنيقة زخارف للحرفيين أيضًا. والسيلادون الكوري الذي يصوّر البشر نادر."],"spots":[["الرقعة","الرقعة بين الاثنين، مربع أبيض."],["الشخص على اليسار","جالس قبالة الرقعة."],["الشخص على اليمين","الخصم الجالس في المقابل."],["الصفصاف","أغصان صفصاف تتدلى فوقهما، مرسومة بالطين الأسود."],["إطار السحب","زخارف ملتفة كالسحب تحيط بالإطار المستدير."],["التشقق","شقوق دقيقة في الطلاء الزجاجي، تتكوّن عند التبريد لأن الطين والطلاء ينكمشان بقدر مختلف."]]},"kangra":{"title":"زوجان يلعبان التشوبار على شرفة","artist":"مجهول","date":"نحو 1790–1800","place":"الهند (باهاري، مدرسة كانغرا)","game":"التشوبار","medium":"رسم بخطوط أولية بالمغرة الحمراء","size":"19.4 × 13.2 سم","credit":"صندوق إدوارد ل. ويتمور، 1936","p":["رسم لفنان من كانغرا في تلال باهاري عند سفوح الهيمالايا. رُسم التخطيط الأول بالأحمر (المغرة الحمراء) ثم ضُبط بالأسود. ولأنه بلا ألوان فوقه، يمكن تتبّع كل خط في الأشخاص والأشياء.","يجلس رجل وامرأة على شرفة على جانبي رقعة على شكل صليب، يلعبان التشوبار، وهي لعبة سباق هندية قديمة على الصليب نفسه الذي تُلعب عليه الباتشيسي، تُحرَّك فيها القطع برمي نرد طويل (باسا). لم تُرسم الخانات على الرقعة بعد. وتقوم وصيفات على خدمة الزوجين."],"spots":[["الرقعة الصليبية","رقعة على شكل صليب على الأرض، لم تُرسم خاناتها بعد."],["المرأة","كفّها إلى الأعلى — هل ستلقي النرد؟"],["الرجل","عمامة بريشة؛ يمد يده نحو الرقعة."],["الوصيفة على اليسار","تحمل قارورة صغيرة وتمد قطعة قماش."],["الوصيفة على اليمين","تحمل أداة طويلة المقبض ووعاء صغيرًا."],["التخطيط الأحمر","حول العمامة يظهر التخطيط الأحمر تحت الخطوط السوداء."]]},"vuillard":{"title":"دور في لعبة الداما (من «مناظر وأماكن داخلية»)","artist":"إدوار فويار","date":"1899","place":"فرنسا","game":"الداما","medium":"طباعة حجرية ملوّنة (الحالة الثالثة من ثلاث)؛ طبعها أوغست كلو ونشرها أمبرواز فولار","size":"الصورة 33 × 25.7 سم (الورقة 38 × 30.8 سم)","credit":"هدية صندوق هانا، 1951","p":["كان أمبرواز فولار، تاجر لوحات الانطباعيين، ناشرًا مهمًا للمطبوعات الفنية أيضًا. ففي 1895 طلب من بيير بونار ألبومًا من 12 طبعة حجرية ملوّنة، ثم نشر ألبومات كثيرة أخرى، منها «مناظر وأماكن داخلية» لفويار، وقد طبعه الطبّاع البارع أوغست كلو.","كان بونار وفويار من جماعة «النبيّين» (أي «الأنبياء» بالعبرية) التي سعت إلى فن جديد يعبّر فيه الشكل واللون بذاتهما عن الشعور، وأحبّت مشاهد المدينة والحياة العائلية. في غرفة تغمرها الزخارف يجلس رجلان متقابلين أمام رقعة الداما، بينما تقف امرأة تتابع اللعب. تُسمّى الداما بالفرنسية «dames»، والكتابة بالقلم الرصاص في أسفل اليسار تُقرأ «partie de dames» أي دور في الداما."],"spots":[["الرقعة","رقعة مربعات صغيرة صُفّت عليها القطع."],["الرجل على اليسار","رجل ملتحٍ يمد يده فوق الرقعة."],["الرجل على اليمين","خصمه، منحنٍ على الرقعة في كرسي بذراعين، تحجبه المرأة الواقفة نصف حجب."],["المرأة الواقفة","يدها على ذقنها، تتابع اللعب."],["المصباح","مصباح قرب الجدار. ورق الجدران والمفروشات مليئة بالزخارف."],["كتابة القلم الرصاص","في أسفل اليسار بالقلم الرصاص: «partie de dames» — دور في الداما."]]},"talbot":{"title":"لاعبا الشطرنج (صورة فوتوغرافية مبكرة)","artist":"يُنسب إلى ويليام هنري فوكس تالبوت","date":"نحو 1843–1847","place":"إنجلترا","game":"الشطرنج","medium":"طبعة على ورق مملّح","size":"19.9 × 15 سم","credit":"اشتُريت بتمويل من السيد والسيدة إيفريت كوفلر","p":["جعلت طريقة السالب والموجب التي ابتكرها تالبوت طبعَ ما يشاء المرء من الصور من سالب واحد ممكنًا، وبقيت أساس التصوير حتى العصر الرقمي. وتُظهر تجاربه المبكرة اهتمامه بالعلم وطموحه الفني معًا، وقد أكّد الباحثون أنه التقط عشر صور أو أكثر للاعبي الشطرنج.","لكن هذه الصورة قد لا تكون من عمله: فنسخ هذا المشهد غير موقّعة، وورقها مختلف عن ورقه المعتاد. ويُرجَّح أن الجالسين هما المصوّر أنطوان كلوديه ومساعد تالبوت نيكولاس هينمان، وتقترح أبحاث حديثة أن الصور التُقطت في استوديو كلوديه، ثم صارت لهينمان، ووصلت إلى تالبوت حين أعطاه هينمان صورًا سدادًا لجزء من دَين (شرح المتحف)."],"spots":[["الرقعة","رقعة الشطرنج على الطاولة، وقطعها مصفوفة."],["صاحب القبعة العالية","يمد يده إلى قطعة وقبعته على رأسه."],["المتأمّل","يده على ذقنه، يتأمل خصمه الرقعة."],["الستارة","ستارة متدلية في الخلف — خلفية للتصوير؟"],["قبعة أخرى","قبعة عالية ثانية على الحامل إلى اليمين."]]},"pvl":{"title":"رجال يلعبون بالنرد","artist":"المعلّم PVL","date":"نحو 1520","place":"الأراضي المنخفضة","game":"النرد","medium":"حفر على النحاس على ورق","size":"9.4 × 9.4 سم (مستديرة)","credit":"مجموعة تشارلز هاك وصندوق عائلة هيرن، اشتُريت 2023","p":["عمل لحفّار مجهول الاسم نشط في الأراضي المنخفضة أوائل القرن السادس عشر، يُعرف بـ«المعلّم PVL» من الحروف المتشابكة «PVL» المحفورة أسفل اليسار. وفي هذه الطبعة المستديرة التي لا تتجاوز راحة اليد، تبني خطوط دقيقة كثيفة عمق الغرفة وملمس الثياب.","على الطاولة نردان. رجل منحنٍ إلى الأمام وشاب بياقة من الفرو يشيران ويتجادلان — ربما على عدد النقاط. وخلفهما نساء يتطلّعن إلى اللعب، وتحت الطاولة إبريق خمر. ارتبط النرد بالقمار منذ القدم، ومُنع مرة بعد مرة."],"spots":[["النردان","نردان يتدحرجان على الطاولة."],["الأيدي المشيرة","إصبعان يلتقيان على الطاولة — جدال على عدد النقاط؟"],["صاحب القبعة العريضة","منحنٍ إلى الأمام، وأكمامه المنفوخة المشقوقة كانت موضة ذلك الزمن."],["الشاب ذو ياقة الفرو","شاب بقبعة كبيرة وياقة من الفرو."],["النساء المتفرجات","نساء يتطلّعن إلى اللعب من الخلف."],["الحروف المتشابكة","«PVL» أسفل اليسار — الدليل الوحيد على اسم الفنان."]]},"kiyohiro":{"title":"لاعبو السوغوروكو","artist":"توري كيوهيرو","date":"نحو 1750","place":"اليابان (عصر إيدو)","game":"بان-سوغوروكو","medium":"طباعة خشبية ملوّنة (بينيزوري-إي)، قطع أوبان؛ الناشر أوروكوغاتايا","size":"43.5 × 29.3 سم","credit":"مجموعة كلارنس باكنغهام","p":["توري كيوهيرو فنان أوكيو-إي نشط من نحو 1737 إلى نحو 1776. وهذه طبعة «بينيزوري-إي» طُبعت بقوالب ألوان قليلة — الوردي (بيني) والأخضر ونحوهما — في السنوات التي سبقت ظهور طبعات «نيشيكي-إي» الكاملة الألوان عام 1765.","اللعبة على الحامل الأسود هي البان-سوغوروكو: يرمي اللاعبان النرد ويحرّكان قطعًا بيضاء وسوداء، ومن يُخرج قطعه كلها أولًا يفوز. وهي من عائلة الطاولة (الباكغامون) نفسها، وكثيرًا ما صوّرت مطبوعات الأوكيو-إي النساء يستمتعن بها. وخلفهما امرأة تدخّن غليونًا طويلًا وتتابع اللعب."],"spots":[["الرقعة","رقعة سوغوروكو على حاملها، عليها قطع بيضاء وسوداء."],["اللاعب على اليسار","يمد يده ليحرّك قطعة."],["المرأة على اليمين","منحنية على الرقعة، تتأمل الخصمة القطع."],["صاحبة الغليون","بغليون كيسيرو طويل تتابع اللعب من الخلف."],["اليد المرفوعة","ترفع المرأة على اليمين شيئًا صغيرًا أسود — كأس النرد؟"],["التوقيع","توقيع «توري كيوهيرو هيتسو» وختم الناشر أوروكوغاتايا."]]},"ingram":{"title":"لعبة الشطرنج الصيني","artist":"جون إنغرام، عن رسم لفرانسوا بوشيه","date":"1741–1763","place":"فرنسا (باريس)","game":"شيانغتشي","medium":"حفر حمضي وحفر بالإزميل","size":"الورقة 39.4 × 27.7 سم (اللوح 24.5 × 16.4 سم)","credit":"مجموعة إليشا ويتلسي، 1966","p":["رسم للرسام الفرنسي فرانسوا بوشيه حفره على النحاس جون إنغرام المولود في لندن. انتقل إنغرام إلى باريس وأنجز بين 1741 و1763 سلسلة مطبوعات عن «الشينوازري» لبوشيه — الصين كما تخيّلها الأوروبيون. والعنوان أسفلها: «LE JEU D'ECHETS CHINOIS» أي لعبة الشطرنج الصيني.","امرأة بشعر مرفوع عاليًا تحرّك قطعة على رقعة في حجرها، وطفل صغير يتفرّج. يُعدّ اللعب شيانغتشي، لكن قطع الشيانغتشي الحقيقية كلها أقراص مسطّحة، أما هنا فقطع طويلة إلى جانب قطع صغيرة مربعة. والنخلة والتمثال الجالس فوق الجرّة أيضًا أقرب إلى البلاد البعيدة التي حلمت بها أوروبا آنذاك منها إلى الصين الحقيقية."],"spots":[["الرقعة والقطع","الرقعة في حجرها، بقطع طويلة ومربعة. قطع الشيانغتشي الحقيقية أقراص مسطّحة."],["اليد على القطعة","يدها اليمنى تحرّك قطعة."],["الخد على اليد","يدها اليسرى على ذقنها، تنظر إلى الرقعة."],["الطفل المتفرّج","طفل واقف قرب الرقعة يتابع اللعب."],["التمثال فوق الجرّة","تمثال جالس متربعًا فوق جرّة كبيرة."],["العنوان والأسماء","«Dessiné par Fr. Boucher» و«Gravé par Ingram» والعنوان «LE JEU D'ECHETS CHINOIS»."]]},"posada":{"title":"لعبة الإوزّة","artist":"خوسيه غوادالوبي بوسادا","date":"1909","place":"المكسيك","game":"لعبة الإوزّة","medium":"طباعة بارزة من لوح زنك على ورق","size":"29.3 × 39.4 سم","credit":"صندوق ويليام ماكالين ماكي التذكاري","p":["ورقة للعب صنعها الحفّار المكسيكي بوسادا — المشهور بهياكله العظمية «الكالافيرا» — لناشر مدينة مكسيكو أنطونيو فانيغاس أرويو. على الشريط أسفل اليسار «JUEGO DE LA OCA» (لعبة الإوزّة)، والمسار يلتفّ من الخانة 1 حتى 63 في الوسط.","في الوسط طُبعت القواعد (EXPLICACION): إن كانت الرمية الأولى 5 و4 فإلى 26، وإن كانت 6 و3 فإلى 53. من يقع على إوزّة (طائر) يعدّ العدد نفسه مرة أخرى؛ وفي النُّزُل (Venta، 19) ينتظر دورين؛ وفي البئر (Poso، 31) والسجن (Carcel، 52) يبقى حتى يأتي غيره؛ والمتاهة (42) تعيده إلى 39، والموت (Muerte، 58) إلى البداية. ويجب الوصول إلى 63 بالضبط. وكان اللاعبون يدفعون رهانًا في خانات معيّنة: فهي لعبة قمار أيضًا."],"spots":[["القواعد","«EXPLICACION» في الوسط: ما تفعله كل خانة ومتى يُدفع الرهان."],["الخانة 1","البداية. من هنا يلتفّ المسار نحو الوسط."],["البئر (31)","بئر كالنافورة. من يقع فيها يبقى حتى يأتي لاعب آخر."],["الموت (58)","خانة الجمجمة: العودة إلى البداية."],["شريط العنوان","«JUEGO DE LA OCA» على الشريط أسفل اليسار، وتحته أطفال يلعبون."],["اسم الناشر","على شريط الإلهة «IMPRENTA DE A. VANEGAS ARROYO»، الدار التي نشرت كثيرًا من مطبوعات بوسادا."]]},"jintile":{"title":"بلاطة لامرأتين تلعبان لعبة رقعة","artist":"مجهول","date":"القرن الثالث عشر","place":"الصين (سلالة جين)","game":"لعبة رقعة (على الأرجح الغو)","medium":"فخار (نقش بارز مصبوب)","size":"الارتفاع 27.3 سم، العرض 24.8 سم، السُّمك 5.4 سم","credit":"اشتُريت بتبرعات أصدقاء الفن الآسيوي، 2002","p":["بلاطة بنقش بارز صُنعت في عهد سلالة جين (1115–1234)، سلالة شعب الجورتشن الذي حكم شمال الصين. تحت شجرة مزهرة تجلس امرأتان متقابلتين على منصة وبينهما رقعة.","على الرقعة شبكة دقيقة، فالأرجح أنهما تلعبان الغو. المرأة على اليمين تنحني وتشير إلى الرقعة، والتي على اليسار تنظر. وكثير من مقابر عصر جين في شمال الصين كانت جدرانها مكسوّة بطوب منقوش بمشاهد من الحياة اليومية، والأرجح أن هذه البلاطة زيّنت مقبرة من هذا النوع."],"spots":[["الرقعة","رقعة دقيقة الشبكة، على الأرجح رقعة غو."],["اليد المشيرة","المرأة على اليمين تشير إلى الرقعة. نقلتها التالية؟"],["المرأة على اليسار","شعرها مرفوع عاليًا، تنظر إلى الرقعة."],["المرأة على اليمين","منحنية نحو الرقعة."],["الشجرة المزهرة","أغصان شجرة مزهرة تمتد فوقهما."],["المنصة","المنصة التي تجلسان عليها، وبين قوائمها زخرفة متموجة."]]},"kyosai":{"title":"ضرطة تقلب دور الغو (من ألبوم رسوم)","artist":"كاوانابي كيوساي","date":"منتصف القرن التاسع عشر إلى أواخره","place":"اليابان (من عصر إيدو إلى ميجي)","game":"الغو","medium":"صفحة مزدوجة من ألبوم مطوي من 26 ورقة مزدوجة؛ حبر وألوان على ورق","size":"الألبوم (مغلقًا) 28 × 18 سم","credit":"هدية آن وأنتوني دوفاي تكريمًا لإيفان تيرنر","p":["مشهد من ألبوم رسوم لكاوانابي كيوساي (1831–1889)، رسام نشط من أواخر عهد الشوغونات إلى عصر ميجي، رُسم بضربات فرشاة سريعة حرة على صفحات ألبوم مطوي. تدرّب كيوساي على تقنية مدرسة كانو الصارمة، وأحبّه الناس أيضًا لرسومه للشياطين وكاريكاتيراته وسخريته.","عنوان المتحف يقول كل شيء: «ضرطة تقلب دور الغو». على اليسار رجل بقلنسوة سوداء ينحني، وعلى اليمين تطير الرقعة في الهواء، وتنثر الأوعية مطرًا من الأحجار، وينقلب الخصم على ظهره. دور جادّ يفسد بضربة واحدة: يسجّل كيوساي بفرشاته السريعة دعابة الضرطة اليابانية القديمة التي عرفتها اللفائف المصوّرة منذ العصور الوسطى."],"spots":[["صاحب القلنسوة السوداء","منحنٍ يُبرز مؤخرته — سبب الفوضى؟"],["الرقعة الطائرة","رقعة الغو المخططة تطير مائلة."],["الأوعية والأحجار","وعاءان ينقلبان والأحجار تتساقط."],["المروحة","مروحة مفتوحة تطير أيضًا قرب الرقعة."],["الخصم المقلوب","ملقى على ظهره، عيناه جاحظتان."],["خط الفرشاة","خطوط حبر قوية كأنها رُسمت دفعة واحدة بلا تخطيط."]]},"yokuts":{"title":"صينية للعب القمار","artist":"ناسجة من شعب يوكوتس (اسمها غير معروف)","date":"نحو 1900","place":"الولايات المتحدة (قرب دنلاب، كاليفورنيا)","game":"هوتشويش (نرد من قشر الجوز)","medium":"ألياف نباتية (نسج لولبي)","size":"الارتفاع 5.1 سم، القطر 61 سم","credit":"اشتُريت بتمويل من السيدة ليونارد س. فلورشايم الابن","p":["كانت شعوب أصلية كثيرة في كاليفورنيا تلعب ألعاب الحظ. وكانت هذه الصينية تُستعمل في «هوتشويش»، وهي لعبة نرد للنساء وحدهن: تُرمى ثمانية أحجار نرد من قشر الجوز على الصينية، وتُحسب النقاط بالعصيّ.","النقش الدائري المنسوج في الصينية يصوّر اللعبة نفسها — النرد وعصيّ العدّ واللاعبات (شرح المتحف). إنها أداة لعب تحمل صورة لعبتها. وفي الصورة أحجار نرد من قشر الجوز على الصينية وحولها."],"spots":[["اللاعبات","أشكال بشرية تدور حول الحافة — المشاركات في اللعب."],["عصيّ العدّ","حزم من خطوط عمودية قصيرة: العصيّ لعدّ النقاط."],["زخارف مستديرة","زخارف صغيرة مستديرة — ربما النرد؟"],["نرد الجوز","نرد من قشر الجوز. كانت ثمانية منها تُرمى على الصينية."],["حزام المثلثات","حزام من مثلثات داكنة يدور حول الصينية."],["المركز","يلتفّ النسج من الوسط، وتحيط به حلقة متقطعة."]]},"hokkei":{"title":"أوشيواكامارو يهزم بنكي في السوغوروكو","artist":"توتويا هوكّي","date":"نحو 1825","place":"اليابان (عصر إيدو)","game":"بان-سوغوروكو","medium":"سوريمونو (طباعة خشبية ملوّنة، قطع شيكيشيبان)","size":"21.8 × 19.1 سم","credit":"هدية هيلين س. غانسولس","p":["سوريمونو لتوتويا هوكّي (1780–1850)، تلميذ هوكوساي. كانت السوريمونو مطبوعات تُطلب طلبًا خاصًا — غالبًا من حلقات الشعر مع قصائدها — وتُطبع بفخامة أكثر من الأوكيو-إي التجارية، بورق جيد وأصباغ معدنية.","أوشيواكامارو، اسم طفولة البطل ميناموتو نو يوشيتسوني، والراهب المحارب العملاق بنكي. لقاؤهما الشهير مبارزة على جسر غوجو في كيوتو، لكن النزال هنا يصبح دورًا في السوغوروكو: يجلس الفتى هادئًا خلف الرقعة، وبنكي ورمحه على ظهره يحكّ رأسه مهزومًا. يبدو أنه تحوير مرح."],"spots":[["رقعة السوغوروكو","رقعة على هيئة صندوق عليها قطع بيضاء وسوداء."],["بنكي يحكّ رأسه","بكامل درعه يحكّ المهزوم رأسه."],["أوشيواكامارو","البطل الفتى جالسًا خلف الرقعة."],["الرمح","نصل ناغيناتا بنكي الكبيرة."],["القصيدة","أبيات أعلى اليمين — على الأرجح من الحلقة التي طلبت المطبوعة."],["التوقيع","توقيع هوكّي في الإطار أسفل اليمين."]]},"vorsterman":{"title":"لاعبو الطاولة (مشهد ليلي)","artist":"لوكاس إميل فورسترمان، عن لوحة لآدم دي كوستر","date":"نحو 1630","place":"الفلاندر (أنتويرب)","game":"الطاولة (باكغامون)","medium":"حفر بالإزميل على ورق عاجي","size":"الصورة 25.5 × 34.4 سم","credit":"مجموعة برنارد ف. روجرز","p":["كان آدم دي كوستر رسامًا بارزًا لمشاهد الليل تحت ضوء الشموع في أنتويرب نحو 1630، حين كان فورسترمان في المدينة نفسها يحفر أعمال معاصريه المشهورين. وكان فورسترمان تلميذًا لروبنز، ثم اختلف مع أستاذه وسافر إلى إنجلترا، فصار يصنع بعدها حفريات أقوى تباينًا وأكثر أسلبة على طريقة كارافاجيو مثل هذه.","حول طاولة في غرفة مظلمة يجتمع رجال أمام رقعة الطاولة. وعلى طريقة دي كوستر في معالجة الضوء، تضيء شعلتا شمعتين الوجوه حول الطاولة (شرح المتحف). وعلى اليمين شاب يحمل عودًا ينظر إلينا."],"spots":[["الرقعة","رقعة طاولة مفتوحة كالصندوق على الطاولة."],["الشمعة","شمعة في شمعدانها، يضيء لهبها الوجوه."],["صاحب الغليون","بقبعة عريضة يدخّن ويتابع اللعب."],["الرجل المولّي ظهره","منحنٍ ويداه على الطاولة."],["عازف العود","شاب يحمل عودًا ويبتسم لنا."],["الأسماء","«A. De Coster pi.» أسفل اليسار، و«Vorsterman» أسفل اليمين."]]},"zorn":{"title":"لاعبو الشطرنج","artist":"أندرس تسورن","date":"1891","place":"السويد","game":"الشطرنج","medium":"حفر حمضي على ورق مخطط عاجي","size":"الصورة 13.5 × 9.6 سم (اللوح 13.9 × 10 سم)","credit":"مجموعتا والاس ل. ديوولف وتشارلز ديرنغ لمطبوعات أندرس تسورن","p":["حفر حمضي للفنان السويدي أندرس تسورن (1860–1920) الذي اشتهر عالميًا بلوحاته الشخصية الزيتية والمائية، وترك أيضًا عددًا كبيرًا من الحفريات. اللوح لا يزيد على حجم الكف.","تكفي خطوط مائلة سريعة متراكبة لتُخرج من النحاس غرفة مظلمة وشخصين. الرجل في المقدمة يولّينا ظهره وينحني فوق الرقعة، والشخص المقابل يطأطئ رأسه مفكرًا في النقلة التالية. رُسمت القطع على الرقعة بخطوط رفيعة. ولا يُعرف من جلس للرسم."],"spots":[["الرقعة والقطع","المنطقة الفاتحة في الأسفل هي الرقعة، والخطوط القصيرة العمودية هي القطع."],["الرجل في المقدمة","يولّينا ظهره منحنيًا فوق الرقعة."],["الخصم","مطأطئ الرأس، عيناه على الرقعة."],["الخلفية المظلمة","عمق الغرفة مبني من خطوط عمودية."],["الخطوط المائلة","المعطف مصنوع من خطوط قطرية سريعة متراكبة."],["التوقيع","توقيع «Zorn» بالقلم الرصاص تحت اللوح."]]},"harunobu-sugoroku":{"title":"مشاهدة اللعب (سوغوروكو)","artist":"سوزوكي هارونوبو","date":"نحو 1766","place":"اليابان (عصر إيدو)","game":"بان-سوغوروكو","medium":"طباعة خشبية ملوّنة (تشوبان، سوريمونو)","size":"28.5 × 21 سم","credit":"مجموعة كلارنس باكنغهام","p":["كان سوزوكي هارونوبو (1725؟–1770) الشخصية المحورية حين ظهرت نحو 1765 مطبوعات «نيشيكي-إي» الكاملة الألوان المطبوعة بقوالب كثيرة. وهذه سوريمونو صدرت طبعًا خاصًا، وتُظهر ألوانها الناعمة المتراكبة ذلك الجديد.","في غرفة يزهر فيها البرقوق تلعب فتاتان على رقعة سوغوروكو على هيئة صندوق، بينما تقف ثالثة وتنظر إليها. قطع بيضاء وسوداء على الرقعة؛ الفتاة على اليسار تحرّك قطعة والتي على اليمين تمد يدها. وعلى الباب المنزلق في الخلف رُسم شلال وأشجار صنوبر."],"spots":[["رقعة السوغوروكو","رقعة بان-سوغوروكو على هيئة صندوق بقطع بيضاء وسوداء."],["الفتاة على اليسار","بكيمونو مزيّن برافعات ورقية، تحرّك قطعة."],["الفتاة على اليمين","منحنية، تمد يدها نحو الرقعة."],["المتفرجة","واقفة تتابع اللعب، وفي يدها شيء طويل المقبض."],["البرقوق","برقوق أبيض يمد أغصانه من الأعلى."],["الباب المرسوم","باب منزلق مرسوم عليه شلال وصنوبر."]]},"kota":{"title":"المهاراو كيشور سينغ الثاني حاكم كوتا يتعبّد لكريشنا في هيئة براج راجي","artist":"مجهول","date":"نحو 1825","place":"الهند (راجستان، كوتا)","game":"الباتشيسي","medium":"تمبرا بالصمغ وفضة وذهب على ورق","size":"24.5 × 18.8 سم","credit":"صندوق جيمس ألبرت وماري غاردينر فورد التذكاري","p":["حاكم إمارة كوتا الصغيرة (حكم 1819–1828)، في زي كاهن من طائفة بوشتي مارغ، يقدّم سراجًا بخمس شعلات. وفي المزار الصغير على المذبح تماثيل معدنية لكريشنا تحفّ به زوجتان — أيقونة لا تُعبد إلا في كوتا.","تتدلى من السقف مصابيح زجاجية كثيرة، وعلى الدرجات المؤدية إلى المذبح ألعاب وأدوات لهو لتسلية كريشنا ورفاقه: فيلة من النحاس الأصفر وأبقار من الفضة وكرات ورقعة باتشيسي (شرح المتحف). القماش الأحمر الصليبي هو تلك الرقعة — الباتشيسي مقدَّمة لعبةً للإله."],"spots":[["رقعة الباتشيسي","القماش الأحمر الصليبي على الدرجات: رقعة باتشيسي."],["الفيلة","فيلان من النحاس الأصفر قرب الرقعة."],["الكرات","كرات ذهبية على الدرجة الأعلى."],["كريشنا","تماثيل كريشنا وزوجتيه في المزار الصغير."],["الحاكم والسراج","في زي كاهن يقدّم سراجًا بخمس شعلات."],["المصابيح الزجاجية","مصابيح زجاجية كثيرة تتدلى من السقف."]]},"coyote":{"title":"لعبة القيوط","artist":"أحد أتباع خوسيه غوادالوبي بوسادا","date":"بلا تاريخ","place":"المكسيك","game":"القيوط والدجاجات (من عائلة الثعلب والإوز)","medium":"طباعة بارزة من لوح زنك على ورق","size":"38.2 × 30.5 سم","credit":"صندوق ويليام ماكالين ماكي التذكاري","p":["ورقة للعب مطبوعة طباعة بارزة من الزنك مثل الأوراق التي صنعها بوسادا للمطابع الشعبية في مدينة مكسيكو. في الأعلى «JUEGO DEL COYOTE» (لعبة القيوط)، وحولها قيوطات تهاجم قنّ الدجاج ورجل يلوّح بعصا لطرد أحدها. وعلى الشريط في الأسفل: «ملك إلديفونسو ت. أوريّانا».","القواعد مطبوعة في «EXPLICACION» أسفل الورقة: لاعبان، مع أحدهما خمس عشرة دجاجة ومع الآخر قيوط واحد. تتقدم الدجاجات إلى الأمام أو إلى الجانب ولا تعود إلى الخلف أبدًا، ويتحرك القيوط في كل الاتجاهات ويأكل الدجاجة بالقفز فوقها إن كانت النقطة خلفها فارغة. وتفوز الدجاجات إذا حاصرت القيوط. إنها لعبة الصيد نفسها التي تُعرف في أوروبا بالثعلب والإوز."],"spots":[["مكان القيوط","رأس القيوط في الدائرة الوسطى: منها يبدأ القيوط."],["أماكن الدجاجات","دوائر عليها دجاجات: هنا توضع قطعها."],["القواعد","«EXPLICACION»: القطع والحركات وكيفية الفوز."],["العنوان","«JUEGO DEL COYOTE» — لعبة القيوط."],["قيوط يطارد دجاجة","في أسفل اليسار قيوط ينقضّ على دجاجة."],["الرجل ذو العصا","في أعلى اليمين رجل يرفع عصا على قيوط."]]},"mons":{"title":"لعب التريكتراك على مونس (برخن)، 1709","artist":"بيتر نولبه (اللوح والناشر)","date":"اللوح 1623–1653؛ الطبع نحو 1709","place":"هولندا (أمستردام)","game":"التريكتراك (من عائلة الطاولة)","medium":"حفر حمضي وحفر بالإزميل وشعر مطبوع بالحروف","size":"الورقة 35.8 × 18.6 سم (اللوح 12.9 × 17.5 سم)","credit":"","p":["أربعة رجال يلعبون التريكتراك إلى طاولة. وبحسب سجل المتحف، تشير الحروف A–D إلى دوق مارلبورو وأمير بافاريا الناخب وسيد أوفركيرك ودوق فيلروا. إنها سخرية من حصار الحلفاء لمونس (برخن بالهولندية) وانتزاعها من الفرنسيين عام 1709، مصوّرة دورًا في لعبة رهانه المدينة. وفي الغرفة الخلفية (E) ملك إسبانيا فيليب الخامس مع امرأة.","اللوح موقّع باسم بيتر نولبه صانعًا وناشرًا، لكن نولبه توفي في أوائل خمسينيات القرن السابع عشر، فالأرجح أن لوحًا قديمًا من القرن السابع عشر أُعيد طبعه بعد إضافة الحروف وقصيدة جديدة. تبدأ القصيدة بالقول إن لعب السادة الكبار ليس إلا تيكتاك وفيركير (لعبتان من هذه العائلة)، ثم تسخر من كل لاعب."],"spots":[["الرقعة","رقعة التريكتراك على الطاولة: الرهان مدينة."],["A، مارلبورو","واقف ينظر إلى الرقعة — القائد الإنجليزي للحلفاء."],["B، أمير بافاريا الناخب","حاسر الرأس، غائص في كرسيه."],["C، أوفركيرك","بقبعة ذات ريش — القائد الهولندي."],["E، الغرفة الخلفية","في غرفة النوم بالخلف فيليب الخامس مع امرأة."],["القصيدة","شعر هولندي مطبوع في الأسفل يسخر من اللاعبين A إلى E."]]},"stembus":{"title":"صندوق الاقتراع: لعبة إوزّة سياسية","artist":"يوهان ميخائيل شميت كرانس (حفّار)","date":"1867","place":"هولندا","game":"لعبة الإوزّة (هجاء)","medium":"طباعة حجرية","size":"66 × 50 سم","credit":"","p":["مطبوعة ساخرة على هيئة لعبة الإوزّة، صدرت مع الأسبوعية «دي نيدرلاندسه سبيكتاتور» العدد 9 بتاريخ 2 مارس 1867، ومعها ورقة منفصلة بالقواعد (سجل المتحف). وفي الخانات صور وزراء ذلك الوقت.","تبدأ اللعبة من بيننهوف، مقر البرلمان في لاهاي، وتنتهي في الوسط عند الخانة 64 «إنسوليندي» — الاسم الشعري لجزر الهند الشرقية الهولندية — حيث تتدلى من جزيرة جاوة صورة الوزير بيتر ماير. كان ماير قد انتقل من وزارة المستعمرات إلى منصب الحاكم العام لجزر الهند، فأثار هذا التعيين عاصفة سياسية. والخانة الزائدة على الخانات الـ63 المعتادة موجودة على الأرجح من أجل هذه النكتة الختامية."],"spots":[["البداية","المبنى أعلى اليسار: تبدأ اللعبة من بيننهوف في لاهاي."],["صورة ماير","الخانة 63: صورة مؤطرة لبيتر ماير معلّقة بالحبال من الجزيرة."],["إنسوليندي 64","الجزيرة والرقم 64 في الوسط: النهاية."],["صندوق الاقتراع","«DE STEMBUS» (صندوق الاقتراع) أسفل اليمين: صندوق العنوان."],["الوزراء","وجوه وزراء ذلك الوقت تطل من الخانات."],["الديك","ديك في إحدى الخانات؛ لا يُعرف ما الذي يسخر منه."]]},"koorai":{"title":"كوريون حول لعبة رقعة (من «نيبون» لسيبولد)","artist":"جيمس إركسليبن (طبّاع حجري)، عن رسم لـ«تويوسكي»","date":"1832–1852","place":"هولندا (لايدن) / أهل كوريا","game":"لعبة رقعة (على الأرجح الغو)","medium":"طباعة حجرية ملوّنة النبرة، ملوّنة يدويًا","size":"الورقة 38 × 55.5 سم","credit":"هدية ف. غ. فالر","p":["لوحة من «نيبون» (NIPPON)، العمل الكبير الذي نشره في لايدن الطبيب الألماني المولد فيليب فرانز فون سيبولد استنادًا إلى ما رآه في المركز التجاري الهولندي في ناغاساكي (1823–1830). في أعلى اليمين «TAB. I» وفي الأسفل «KOORAI» (كوريا)، ومعها «أسرة صياد» بالهولندية والألمانية. رسمها إركسليبن على الحجر، وتذكر اللوحة أن واضع الرسم «تويوسكي».","أربعة رجال جالسون على الأرض حول رقعة؛ على اليسار امرأة تقود طفلًا صغيرًا، وعلى اليمين رجل واقف يحمل عصا طويلة وكيسًا. وأمامهم قبعة سوداء عريضة الحافة (غات) على الأرض. تُظهر الرقعة شبكة وأحجارًا مستديرة، فالأرجح أنها الغو (بادوك بالكورية)، مع أن السجل يقول «لعبة رقعة» فقط."],"spots":[["الرقعة","شبكة عليها أحجار مستديرة: على الأرجح دور غو."],["القبعة السوداء","قبعة سوداء عريضة الحافة (غات) على الأرض."],["الأم والطفل","امرأة تمسك بيد طفل وتتابع اللعب."],["الرجل الواقف","واقف يحمل عصا طويلة وكيسًا."],["الرجل المنحني","بسترة زرقاء ينظر في الرقعة."],["العنوان","«KOORAI» (كوريا)، ومعها «أسرة صياد» بالهولندية والألمانية."]]},"cairo":{"title":"جماعة حول لعبة رقعة أمام مقهى (القاهرة)","artist":"دولييه وبيشار (إيبوليت دولييه وإميل بيشار)","date":"نحو 1869–1890","place":"مصر (القاهرة)","game":"لعبة رقعة (على الأرجح الشطرنج)","medium":"طبعة ألبومين","size":"10.8 × 16.4 سم","credit":"","p":["صورة لإيبوليت دولييه وإميل بيشار، مصوّرَين فرنسيَّين كان لهما استوديو في القاهرة. على الكرتون اسم الاستوديو «عند حديقة الأزبكية» و«القاهرة (مصر)». وكان المسافرون يشترون مثل هذه الصور تذكارًا من مصر.","رجال جالسون على الأرض أمام دكان بنافذة مشربية، يحيطون برقعة على حامل منخفض. على الرقعة قطع طويلة قائمة، فالأرجح أنها الشطرنج، مع أن سجل المتحف يقول «لعبة رقعة» فقط. الجميع ساكنون من أجل التعريض الطويل."],"spots":[["الرقعة والقطع","الرقعة على حامل منخفض بقطع طويلة: على الأرجح الشطرنج."],["نافذة المشربية","نافذة بشبكة خشبية، من سمات بيوت القاهرة القديمة."],["الرجل ذو العصا","جالس بعصاه يتابع اللعب."],["السلة","سلة مجدولة على الأرض."],["الطفل المتفرّج","طفل يطل على الرقعة من الخلف."],["اسم الاستوديو","«AU JARDIN DE L’ESBÉKIEH» و«CAIRE (EGYPTE)» على الكرتون."]]},"vanmour":{"title":"جماعة من الأرمن يلعبون الورق","artist":"جان باتيست فانمور","date":"نحو 1720–1737","place":"الدولة العثمانية (إسطنبول)","game":"الورق","medium":"زيت على قماش","size":"44.5 × 58.5 سم","credit":"","p":["وُلد فانمور في الفلاندر، وذهب إلى إسطنبول سنة 1699 مع السفير الفرنسي، وعاش في المدينة حتى وفاته يرسم مراسم البلاط وحياة أهلها اليومية. ويذكر المتحف أن ملابس الرجال تدل على أنهم أرمن.","على ضوء شمعة كبيرة يلعب رجال ونساء الورق حول مائدة مغطاة بقماش أحمر. على المائدة أوراق موزعة، وبعضهم يتأمل الأوراق في يده. وفي الركن الأيسر امرأة عجوز تغزل. لا يذكر السجل أي لعبة هي."],"spots":[["الأوراق على المائدة","أوراق على المائدة ذات القماش الأحمر."],["الشمعة الكبيرة","شمعة واحدة تضيء الجماعة كلها."],["العجوز الغازلة","امرأة عجوز تغزل في الركن الأيسر."],["امرأة تنظر في أوراقها","في أقصى اليمين امرأة تتأمل أوراقها."],["الرجل ذو الفراء","رجل بمعطف محفوف بالفراء؛ تدل الملابس على أنهم أرمن."],["منحنٍ على المائدة","شخص ينحني على المائدة والأوراق في يده."]]},"algiers":{"title":"ثلاثة رجال يلعبون لعبة رقعة (الجزائر العاصمة)","artist":"مجهول","date":"1851–1900","place":"الجزائر (الجزائر العاصمة)","game":"لعبة رقعة (على الأرجح الطاولة)","medium":"طبعة ألبومين","size":"14.0 × 10.0 سم","credit":"","p":["صورة لمصوّر مجهول كُتب تحتها بخط اليد «Alger» (الجزائر). الكراسي والطاولة الصغيرة أمام خلفية سادة تدل على أنها التُقطت على الأرجح في استوديو. وكان المسافرون وجامعو التحف يشترون مثل هذه الصور لأهل شمال أفريقيا.","رجلان متقابلان أمام رقعة ذات حافة، والرجل الأيمن يمد يده إلى قطعة. على الرقعة قطع مستديرة مكدسة، فالأرجح أنها الطاولة (النرد)، مع أن السجل يقول «لعبة رقعة» فقط. وعلى الطاولة الصغيرة في المقدمة أدوات القهوة."],"spots":[["الرقعة والقطع","رقعة ذات حافة عليها قطع مستديرة مكدسة."],["المتفرج الواقف","رجل بحزام على خصره يقف خلفهما ويتابع اللعب."],["الشيخ على اليسار","رجل مسن معصوب الرأس غارق في التفكير."],["الرجل على اليمين","بغطاء أبيض على رأسه ينحني على الرقعة."],["أدوات القهوة","صينية وفناجين صغيرة على طاولة مخرّمة."],["اليد التي تلعب","يد اللاعب الأيمن توشك أن تأخذ قطعة."]]},"circo":{"title":"لعبة السيرك (خويغو ديل سيركو)","artist":"مانويل مانيّا (؟)","date":"غير مؤرخ","place":"المكسيك","game":"لعبة رهان بنردين","medium":"حفر بارز أو حفر ضوئي بارز على ورق أسمر فاتح","size":"26.2 × 35.0 سم","credit":"","p":["ورقة لعب تُنسب، مع علامة استفهام، إلى الحفّار المكسيكي مانويل مانيّا. في أسفلها إلى اليمين اسم بائعها، مطبعة الصور «إل تياترو»، وعنوانها. كانت مثل هذه الأوراق الرخيصة تُباع في الشوارع، ويبدو أنهم كانوا يلعبون عليها كما هي.","في الوسط خيمة سيرك، وحولها فرسان بهلوانيون وبرج بشري ورجل قوي وغيرهم، ولكل صورة رقم من 2 إلى 12. ويقول «الشرح» أعلى اليسار إن الجميع، والأطفال أيضًا، يمكنهم اللعب: يُرمى نردان ويوضع الرهان على الخانة المطابقة، أو يُؤخذ ما عليها. ومن يرمي اثني عشر يأخذ كل شيء."],"spots":[["خيمة السيرك","عنوان «JUEGO DEL CIRCO» والخيمة، وهي الخانة 12."],["قواعد اللعب","القواعد تحت عنوان «ESPLICACION»."],["الفارسة البهلوانة","راقصة على ظهر حصان يعدو: الخانة 6."],["البرج البشري","رجل واقف على كتفي آخر: الخانة 4."],["الرجل القوي","رجل يرفع ثقلًا على شكل مدفع: الخانة 8."],["اسم المطبعة","«De venta, Estampería “El Teatro”» والعنوان."]]},"loteria":{"title":"بطاقات صور لعبة اللوتيريا","artist":"خوسيه غوادالوبي بوسادا","date":"1880–1913","place":"المكسيك","game":"اللوتيريا (لعبة المناداة بالصور)","medium":"حفر بارز أو حفر ضوئي بارز على ورق أسمر فاتح","size":"30.0 × 40.0 سم","credit":"","p":["رسم الحفّار المكسيكي بوسادا صورًا لا تُحصى للناشر أنطونيو فانيغاس أرويو في مدينة مكسيكو، الذي كانت أوراقه الرخيصة تحمل الأخبار والأغاني والألعاب. وعلى هذه الورقة عنوان «JUEGO DE LOTERIA» واسم فانيغاس أرويو.","تملأ الورقة ثمانٍ وثلاثون صورة صغيرة مع أسمائها: النجمة والقمر والعقرب والشيطان والجمجمة والديك والمطبعة وغيرها. في اللوتيريا، الشبيهة بالبنغو، يسحب المنادي البطاقات ويعلن الصور، فيعلّمها اللاعبون على ألواحهم بالفول أو نحوه. والأرجح أن الورقة كانت تُقصّ بطاقات."],"spots":[["العنوان والناشر","«JUEGO DE LOTERIA» واسم دار فانيغاس أرويو."],["النجمة","«ESTRELLA»، أول صورة أعلى اليسار."],["القمر","«LUNA»، هلال له وجه."],["الموت","«MUERTE»: هيكل عظمي يحمل منجلًا ويعزف على مزمار."],["جامع عصارة الصبّار","«TLACHIQUERO»: رجل يجمع عصارة الأغاف."],["المطبعة","«IMPRENTA»: عمال عند المكبس، حيث كانت تُطبع مثل هذه الأوراق."]]},"jeupol":{"title":"«اللعبة البولندية» أو رقعة الضامة","artist":"مجهول","date":"1833–1900","place":"بلجيكا أو هولندا","game":"الضامة (رقعة 10 × 10)","medium":"حفر على الخشب مع نص مطبوع بالحروف","size":"32.2 × 39.6 سم","credit":"","p":["ورقة مفردة عنوانها بالفرنسية والهولندية «JEU POLONAIS OF DAMSPEL». و«اللعبة البولندية» اسم فرنسي للضامة على رقعة 10 × 10. وفي أعلى اليمين رقم الناشر التسلسلي «n. 106».","كما يذكر سجل المتحف، فيها 100 خانة، 50 بيضاء و50 سوداء، مع إطارين مزخرفين يمينًا ويسارًا. لم تُطبع القطع، فالأرجح أنها رقعة رخيصة يُلعب عليها كما هي بالفول أو الأزرار. وما زالت آثار الطي ظاهرة في الورق."],"spots":[["العنوان","كلمات «JEU POLONAIS OF DAMSPEL»."],["الرقم التسلسلي","رقم الناشر «n. 106»."],["الإطار الأيسر","عمود من زخارف وردية مستديرة."],["الإطار الأيمن","الزخرفة نفسها في الجهة الأخرى."],["المئة خانة","رقعة 10 × 10؛ الخانات الداكنة مظللة بخطوط دقيقة."],["أثر الطي","أثر طي في الورق؛ ربما كانت تُحمل مطوية."]]},"dkaart":{"title":"دومينو وورق لعب للقص","artist":"مجهول (منشورات بريبولس)","date":"1800–1833","place":"بلجيكا (تورنهاوت)","game":"الدومينو والورق","medium":"حفر على الخشب ملوّن بالأزرق والأحمر والأصفر؛ نص مطبوع","size":"34.3 × 41.9 سم","credit":"","p":["بحسب سجل المتحف، تحمل الورقة 32 ورقة لعب و28 قطعة دومينو لتُقص وتُستعمل. وهي رقم 114 في قائمة الناشر بريبولس، وفي أسفلها اسم البائع «د. باوفلس، بيرخن أوب زوم». والعنوان بالهولندية والفرنسية.","إلى اليسار تتراص قطع الدومينو الـ28 من الأبيض المزدوج إلى الستة المزدوجة على شكل مثلث. وإلى اليمين 32 ورقة، من السبعة إلى العشرة مع الصور والآسات من كل نوع: مجموعة لألعاب مثل البيكيه. ولأن أحدًا لم يقصّها نراها كما خرجت من المطبعة."],"spots":[["العنوان","كلمات «DOMINO EN KAARTSPEL»."],["الأبيض المزدوج","رأس المثلث: القطعة بلا نقاط."],["الستة المزدوجة","أكبر قطعة، في طرف الصف الأسفل."],["آس البستوني","الورقة الثانية في العمود الأيسر."],["ورقة مصوّرة","ملك ملوّن بالأحمر والأزرق والأصفر."],["البائع","«D. POUWELS, Bergen-op-Zoom» في الأسفل."]]},"apen":{"title":"قردان يلعبان التريكتراك","artist":"كويرين بول، عن رسم ديفيد تينيرز","date":"1635–1690","place":"الفلاندر","game":"التريكتراك (من أقارب الطاولة)","medium":"حفر بالحمض","size":"11.0 × 14.5 سم","credit":"","p":["لوحة من سلسلة، صفحة عنوان وست لوحات، تمثّل فيها القرود أعمال البشر. في أسفل اليسار: «د. تينيرز ابتكر ونشر، بامتياز»؛ فقد حفر كويرين بول تصميم الرسام الفلمنكي تينيرز.","كما يصف سجل المتحف، يجلس قردان على الأرض وبينهما رقعة تريكتراك. الأيسر يشرب النبيذ من كأس، والأيمن بقبعة فيها ريشة ديك يمد يده إلى قطعة. والأرجح أنها سخرية من الناس المنغمسين في الشراب والقمار."],"spots":[["الرقعة","رقعة تريكتراك مطوية على الأرض، بخاناتها وقطعها."],["القرد الأيسر","قرد يرتدي سترة جالس أمام الرقعة."],["كأس النبيذ","الكأس التي يرفعها القرد الأيسر."],["القبعة ذات الريشة","ريشة ديك في قبعة القرد الأيمن."],["الإبريق","إبريق عند قدمي القرد الأيسر."],["الكتابة","«D Teniers in et excud cum privilegio»."]]},"dstereo":{"title":"رجال يلعبون الدومينو إلى مائدة (صورة مجسّمة)","artist":"مجهول","date":"1850–1880","place":"غير معروف (كتابة بالهولندية)","game":"الدومينو","medium":"طبعة ألبومين (صورة مجسّمة)","size":"8.5 × 17.0 سم","credit":"","p":["صورة مجسّمة: صورتان متطابقتان تقريبًا جنبًا إلى جنب. حين يُنظر إليهما بالمجسام تندمجان في مشهد واحد له عمق. وعلى الحافة اليسرى كُتب باليد «Het dominospel» (لعبة الدومينو).","وُضعت مائدة في الشمس أمام مبنى، ورجال بقمصانهم يمسكون قطع الدومينو. اثنان واقفان يتابعان اللعب، والرجل الأيمن يعتمر طاقية بيضاء. ولأن الجميع كان عليهم الثبات، فالأرجح أن المشهد رُتّب للكاميرا."],"spots":[["القطع على المائدة","قطع دومينو مقلوبة في الأيدي."],["ذو الطاقية البيضاء","جالس إلى اليمين يمسك قطعه."],["ذو المنديل","واقف ينظر إلى اللعب من أعلى."],["الرجل الأيسر","شاب متكئ على مرفقه ينظر في قطعه."],["الكتابة","«Het dominospel.» على الحافة اليسرى."],["الصورة الثانية","الصورة اليمنى، مأخوذة من نقطة مزاحة قليلًا؛ معًا تبدوان مجسّمتين."]]},"gojo":{"title":"امرأتان تلعبان الغو","artist":"مجهول","date":"1870–1891","place":"اليابان","game":"على الأرجح الغو","medium":"طبعة ألبومين ملوّنة يدويًا","size":"9.0 × 13.5 سم","credit":"","p":["صورة بالأبيض والأسود لُوّنت باليد بالفرشاة. كانت مثل هذه الصور تُصنع في استوديوهات يوكوهاما وغيرها تذكارات للأجانب. وكانت هذه ملصقة في ألبوم صور لرحلة إلى مانيلا.","أمام زينة كالمحراب وستارة قابلة للطي تجلس امرأتان على جانبي رقعة ذات أرجل، والتي على اليسار تضع حجرًا. على الرقعة أحجار بيضاء وسوداء، فالأرجح أنها لعبة الغو، مع أن سجل المتحف يقول «لعبة رقعة». وعلى الصينية في المقدمة حلوى وأوانٍ."],"spots":[["الرقعة والأحجار","رقعة سميكة ذات أرجل عليها أحجار بيضاء وسوداء."],["اليد التي تلعب","المرأة اليسرى تضع حجرًا."],["المرأة على اليسار","تلتفت نحونا؛ وحزامها معقود عقدة كبيرة."],["المرأة على اليمين","بكيمونو مخطط، ويدها قرب الرقعة."],["الصينية والأواني","حلوى وفناجين في المقدمة."],["الزهور","مزهرية على حامل في الخلف."]]},"meade":{"title":"رجلان يلعبان الشطرنج","artist":"تشارلز ريتشارد ميد وهنري ويليام ماثيو ميد","date":"1852","place":"الولايات المتحدة","game":"الشطرنج","medium":"داغيروتايب","size":"6.9 × 8.3 سم","credit":"","p":["صورة داغيروتايب من استوديو الأخوين ميد، مصوّرَين وُلدا في إنجلترا وعملا في أمريكا. تتكون صورة الداغيروتايب مباشرة على لوح نحاسي مطلي بالفضة، فكل واحدة فريدة لا تُنسخ؛ وهذه محفوظة في علبة جلدية صغيرة خلف إطار مذهّب.","شابان أمام رقعة شطرنج على منضدة صغيرة؛ الأيسر يضع أصابعه على قطعة. والأيمن، ويده على صدره، يتأمل الرقعة. ولأن عليهما الثبات طويلًا، فالأرجح أن النقلة مصطنعة للتصوير."],"spots":[["رقعة الشطرنج","الرقعة والقطع البيضاء على منضدة مغطاة بقماش مزهّر."],["الرجل الأيسر","أصابعه على قطعة."],["الرجل الأيمن","ينظر إلى الرقعة."],["اليد على الصدر","يد اللاعب الأيمن المتأملة."],["القماش","منضدة صغيرة مغطاة بقماش مزهّر."],["الإطار المذهّب","الإطار والعلبة اللذان يحميان اللوح."]]},"weiqidai":{"title":"منظر طبيعي مع خالدين طاويين يلعبون الويتشي","artist":"يُنسب إلى داي جين","date":"سلالة مينغ، القرنان 15–16","place":"الصين","game":"الويتشي (الغو)","medium":"لفافة معلّقة؛ حبر وألوان على حرير","size":"175.2 × 106.7 سم","credit":"","p":["لفافة معلّقة كبيرة تُنسب إلى رسام عصر مينغ داي جين (نحو 1388–1462). كان من جيجيانغ واشتهر بمناظره القوية، وعُدّ لاحقًا مؤسس مدرسة جي. وتحت جروف شاهقة وشجرة ضخمة رُسم الناس صغارًا.","في الظل على الأرض يجلس خالدان أمام رقعة ويتشي مخططة، وبجانبهما طبق فاكهة وجرة. والشخص الجاثم على اليسار يذكّر بالحطّاب الذي ظل يتفرج على لعب الخالدين في الجبل حتى تعفّن مقبض فأسه (أسطورة لانكه)، مع أن عنوان المتحف لا يذكر إلا خالدين طاويين يلعبون الويتشي."],"spots":[["الرقعة","رقعة ذات حافة بشبكة دقيقة."],["الخالد الملتحي","خالد طويل اللحية جالس في هدوء."],["الخالد ذو القلنسوة الزرقاء","منحنٍ على الرقعة؛ وعند ركبته وعاء أحجار."],["الشخص الجاثم","يطل على الرقعة من اليسار؛ لعله حطّاب الأسطورة."],["الفاكهة والجرة","طبق وجرة وراء الرقعة."],["التوقيع والأختام","توقيع وختمان أحمران أعلى اليمين."]]},"reise":{"title":"الرحلة حول العالم، برًا وبحرًا","artist":"مجهول","date":"القرن التاسع عشر","place":"على الأرجح البلاد الناطقة بالألمانية","game":"لعبة سباق بنرد واحد على رهان","medium":"طباعة حجرية","size":"42.5 × 33.7 سم","credit":"","p":["ورقة لعب عنوانها بالألمانية «الرحلة حول العالم، بحرًا وبرًا: لعبة نرد جديدة ومسلية». على رقعة مستديرة خانات من 1 إلى 41، فيها صور منطاد وسفن شراعية وسفينة بخارية وقاطرة وأناس من أمم شتى وغير ذلك. وفي أسفل اليمين الرقم «No. 107».","وفي الأسفل قواعد اللعب بالألمانية والإنجليزية والهولندية والفرنسية. يدفع كل لاعب أولًا 15 ماركًا في «كيس الرحلة» المشترك، ثم يرمي نردًا واحدًا بالدور ويحرّك علامته. من يقف على صورة كبيرة يربح ماركين، والرقم بلا صورة غرامته ماركان، ومن يبلغ 41 يأخذ كل الباقي."],"spots":[["41: عربة البريد","الهدف في الوسط: عربة بركاب وحوذي."],["1: الإنجليزي","خانة البداية، «Engländer» بقبعة عالية."],["المنطاد","خانة فيها منطاد في السماء."],["السفينة الشراعية","سفينة بأشرعة منشورة."],["القاطرة","قاطرة بخارية ينبعث منها الدخان."],["القواعد","القواعد مطبوعة بأربع لغات."]]},"huchten":{"title":"النرد على الحياة أو الموت","artist":"يان فان هوختنبورخ","date":"1680–1720","place":"هولندا","game":"النرد","medium":"زيت على قماش","size":"67.5 × 76.0 سم","credit":"","p":["من أعمال الرسام الهولندي يان فان هوختنبورخ (1647–1733) المعروف بمشاهد المعارك، وعليها توقيعه أسفل اليسار. وعنوانها في المتحف «لعبة النرد على الحياة». خارج حصن يرمي سجينان النرد على طبل، ويحيط بهما ضباط وجنود.","في الخلف إلى اليمين مشنقة، ومن سور الحصن على اليسار يتفرج جنود آخرون. والأرجح أنها تصوّر جنودًا محكومًا عليهم يقترعون بالنرد على من سيُعدم. أحد السجينين يشير إلى الطبل، والآخر جاثٍ ينظر إلى الرمية."],"spots":[["الطبل والنرد","طبل يقوم مقام المائدة التي يُرمى عليها النرد."],["السجين المشير","واقف يشير إلى الطبل."],["السجين الجاثي","بقميص أبيض منحنٍ على الطبل."],["الضابط الفارس","بقبعته ينظر من فوق حصانه."],["المشنقة","المشنقة أعلى اليمين."],["الجنود على السور","جنود يتفرجون من سور الحصن."]]},"vertu":{"title":"لعبة الفضيلة (Spel der Deugd)","artist":"يان خيريتس فيسر (من تصميم ي. فورمان)","date":"1798","place":"هولندا","game":"لعبة رهان بنردين","medium":"حفر بالإزميل وبالحمض وطباعة بالحروف","size":"56.9 × 38.0 سم","credit":"","p":["ورقة لعب كبيرة عنوانها بالهولندية والفرنسية «لعبة الفضيلة». في وسط معبد ذي أعمدة تجلس الفضيلة، وعن يسارها الرخاء وعن يمينها الفقر. على الأعمدة ميداليات لفضائل كالإخلاص والامتنان والمحبة، وعلى القواعد في الأسفل رذائل كالبخل والكبر والكسل.","بحسب القواعد في الأسفل، تُلعب بنردين أو بسحب القرعة. بالنرد يراهن اللاعبون بـ63 معًا ثم يرمون بالدور في اتجاه سير الشمس. كل رمية تسمّي فضيلة أو رذيلة: الستتان «الفضيلة» تأخذ الرهان كله، والواحدان «الرذيلة» تدفع ثمانية. وتحت كل صورة «T» لما يُؤخذ و«B» لما يُدفع."],"spots":[["العنوان","«SPEL DER DEUGD» في الجبهة المثلثة."],["الفضيلة","الفضيلة على العرش في الوسط؛ الستتان تأخذان كل شيء."],["الرخاء","الرخاء ومعه قرن الوفرة."],["الرذيلة","الواحدان، الرذيلة: طفل يرفع كأسًا."],["البخل","البخل على القاعدة؛ «B» والنرد يبيّنان ما يُدفع."],["القواعد","القواعد مطبوعة متراصة في الأسفل."]]},"charros":{"title":"الشارّوس المهرّبون: لعبة نرد","artist":"خوسيه غوادالوبي بوسادا","date":"غير مؤرخ","place":"المكسيك","game":"لعبة سباق بثلاثة أحجار نرد","medium":"طباعة حجرية","size":"29.9 × 40.4 سم","credit":"","p":["لعبة سباق برسوم بوسادا، عنوانها «LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS» (الشارّوس المهرّبون / لعبة نرد). في الأسفل اسم مطبعة أ. فانيغاس أرويو في مكسيكو، ووقّع بوسادا أسفل اليمين. والشارّوس فرسان مكسيكيون يعدون بقبعاتهم العريضة في الأركان.","خانات مستديرة محاطة بالحبال تتلوى على الرقعة كلها، فيها حيوانات وأناس وقطار وغير ذلك. ويقول «الشرح» أعلى اليمين إن اللعب بثلاثة أحجار نرد. ثلاثة آحاد في الرمية الأولى فوز، والوقوع على الجمجمة خسارة؛ عند الغزال تأخذ من الصندوق، وعند اللصوص تدفع، وعند الأسد تبقى حتى يأتي غيرك."],"spots":[["العنوان","«LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS»."],["الشرح","القواعد تحت «EXPLICACION»."],["اللاعبون","أناس حول مائدة يلعبون على رقعة، أسفل اليسار."],["النرد","ثلاثة أحجار نرد مرسومة وسط الرقعة."],["الشارّو الفارس","شارّو يعدو ويدير حبله."],["المطبعة","«IMPRENTA DE A. VANEGAS ARROYO, MÉXICO»."]]},"snuffwq":{"title":"قارورة سعوط عليها لاعبو الويتشي","artist":"الصين","date":"سلالة تشينغ، علامة عهد داوغوانغ وزمنه (1820–1850)","place":"الصين","game":"الويتشي (الغو)","medium":"بورسلين مرسوم بمينا فوق الطلاء الزجاجي","size":"الارتفاع 5.7 سم","credit":"","p":["قارورة صغيرة لحمل السعوط في الصين أيام أسرة تشينغ. ويذكر سجل المتحف أن عليها علامة عهد داوغوانغ وأنها من 1820–1850. وعلى بدنها من البورسلين الأبيض، بارتفاع نحو ستة سنتيمترات، رُسم منظر جبلي وأشخاص بالمينا.","قرب صخرة كالمغارة يجلس شيخان أمام رقعة ويتشي على حامل أزرق، والأيسر يوشك أن يضع حجرًا. ومن خلفه يتفرج صبي يحمل عصا. والأرجح أن الموضوع يذكّر بقصة الحطّاب الذي تفرّج على لعب الخالدين."],"spots":[["الرقعة","رقعة على حامل أزرق بشبكة دقيقة."],["الشيخ الملتحي","بثوب بنفسجي يمد يده إلى الرقعة."],["الشيخ المقابل","جالس إلى اليمين رافعًا يده."],["الصبي ذو العصا","يتفرج من الخلف."],["المغارة","صخرة كالمغارة خلف اللاعبين."],["السدادة","سدادة خضراء."]]},"ostade":{"title":"لاعبو التريكتراك في خمّارة","artist":"أدريان فان أوستاده","date":"1653","place":"هولندا (هارلم)","game":"التريكتراك (من أقارب الطاولة)","medium":"حفر بالحمض","size":"8.5 × 7.4 سم","credit":"","p":["حفر بحجم الكف للرسام الهارلمي أوستاده المعروف بمشاهد حياة الفلاحين، وعليه توقيع «A. ostade» في الأسفل. في خمّارة معتمة يسقط ضوء نافذة ذات إطار رصاصي على الناس.","على المائدة اليسرى رجلان متقابلان أمام رقعة تريكتراك، وثالث يطل من خلفهما. وعلى اليمين رجل مستند إلى الجدار وفي يده كوب. وإبريق كبير ملقى على الأرض؛ كأنها عصرية كسولة في الخمّارة."],"spots":[["الرقعة","رقعة تريكتراك على المائدة."],["اللاعب الأيسر","رجل بقبعة يواجه الرقعة."],["اللاعب الأيمن","منحنٍ على الرقعة."],["المتفرج","رجل واقف خلفهما يراقب."],["الرجل المستريح","جالس عند الجدار وفي يده كوب."],["النافذة الرصاصية","نافذة بزجاج معيّن يدخل منها الضوء."]]},"lenain":{"title":"لاعبو النرد","artist":"أحد أتباع ماتيو لو نان","date":"1630–1680","place":"فرنسا","game":"النرد","medium":"زيت على قماش","size":"92.8 × 119.7 سم","credit":"","p":["عمل لأحد أتباع ماتيو، أصغر الإخوة لو نان الفرنسيين. ويذكر المتحف أن رسمًا تمهيديًا لتكوين مشابه بيد غابرييل دو سان-أوبان محفوظ في المكتبة الوطنية بباريس.","ثلاثة رجال حول مائدة مستديرة صغيرة في الهواء الطلق يرمون النرد، واثنان يتفرجان، والأيسر يحتضن زجاجة. وإلى اليمين كلبا صيد نحيلان، ووراء الفتحة منظر واسع. والأشياء البيضاء الصغيرة على المائدة هي النرد."],"spots":[["النرد على المائدة","نرد على المائدة المستديرة."],["ذو القبعة الفاتحة","جالس يمد يده ليتفقد الرمية."],["ذو الثياب السوداء","شاب واقف ويده على خصره."],["الفتى في الخلف","يتابع اللعب من وراء المائدة."],["حامل الزجاجة","على اليسار يبتسم لنا."],["كلبا الصيد","كلبان نحيلان على اليمين."]]},"tunisie":{"title":"لعب الورق أمام مقهى عربي (الجناح التونسي في معرض أنتويرب العالمي)","artist":"مجهول (طباعة ش. برنهوفت)","date":"1894","place":"بلجيكا (أنتويرب)","game":"الورق","medium":"طباعة كولوتايب","size":"15.4 × 21.6 سم","credit":"","p":["لوحة من مجموعة من 49 لوحة عن معرض أنتويرب العالمي سنة 1894، كُتب في أعلاها «EXPOSITION UNIVERSELLE D’ANVERS 1894» وفي أسفلها «تونس. لعب الورق أمام مقهى عربي». وطبعها برنهوفت، مصوّر البلاط في لوكسمبورغ.","التُقطت في ساحة ذات قباب ومئذنة بُنيت للجناح التونسي في المعرض. رجال بلباس تونسي يلعبون الورق حول طاولات صغيرة مكسوة بالبلاط؛ أحدهم يدخّن الشيشة، وقربهم صينية فناجين. وإلى اليمين يجلس زوار ببدلات: والأرجح أنه عرض لحياة بلد بعيد."],"spots":[["طاولة اللعب","رجال يمسكون الورق حول طاولة مكسوة بالبلاط."],["الشيشة","خرطوم الشيشة في فم الرجل الأيسر."],["الزوار ببدلاتهم","رجال ببدلات يجلسون يمينًا، والأرجح أنهم زوار المعرض."],["صينية الفناجين","فناجين صغيرة تحت الطاولة."],["القباب والمئذنة","مبانٍ على الطراز التونسي شُيّدت للمعرض."],["التعليق","«TUNISIE» و«PARTIE DE CARTES DEVANT UN CAFÉ ARABE»."]]},"laghouat":{"title":"قُوّاد من نواحي الأغواط","artist":"مجهول","date":"1880–1890","place":"الجزائر (نواحي الأغواط)","game":"على الأرجح الدومينو","medium":"طبعة ألبومين","size":"20.9 × 27.0 سم","credit":"","p":["صورة بعنوان «أنماط جزائرية. قُوّاد من نواحي الأغواط»، ملصقة في ألبوم وعليها الرقم المطبوع «239». والقائد لقب زعيم محلي في الجزائر تحت الحكم الفرنسي.","رجال بجلابيب بيضاء جالسون على حصير أمام جدار طيني، يصفّون قطعًا مستطيلة على طاولة واطئة. ومن طريقة صفّها فالأرجح أنها الدومينو، مع أن سجل المتحف يقول «لعبة» فقط. وفي المقدمة صينية شاي والبلاغي التي خلعوها."],"spots":[["القطع على الطاولة الواطئة","قطع مستطيلة مصفوفة في صف على الطاولة."],["صينية الشاي","كؤوس وإبريق على صينية في المقدمة."],["البلاغي","أحذية متروكة قرب الحصير."],["الواقف","شخص واقف قرب الجدار يتفرج."],["الجدار الطيني","الجدار الترابي الخشن في الخلف."],["الحصير","الحصير المجدول الذي يجلسون عليه."]]},"hangong":{"title":"سيدات القصر (صباح ربيعي في قصر هان)، تفصيل","artist":"نسخة عن تشيو ينغ","date":"سلالة تشينغ (1644–1911)","place":"الصين","game":"الويتشي (الغو)","medium":"لفافة أفقية؛ حبر وألوان على حرير","size":"36.2 × 454.4 سم (اللفافة كاملة)","credit":"","p":["تفصيل من لفافة أفقية يزيد طولها على أربعة أمتار ونصف، وهي نسخة من عصر تشينغ لتكوين رسام عصر مينغ تشيو ينغ (1494–1552). في قصر في يوم ربيعي تتأرجح سيدات البلاط والفتيات والوصيفات، ويلعبن، ويتأملن الفاوانيا، ويعزفن الموسيقى والتشين، ويطعمن ببغاء وأسماكًا.","في هذا المشهد تجلس امرأتان متقابلتان أمام رقعة ويتشي خلف درابزين، وتنحني أخريات للمشاهدة. وفي المقدمة حجر زينة في حوض على شكل لوتس، ووصيفات يحملن آلات وصررًا. وكما يذكر المتحف، تجعل اللفافة حياة النساء في الأجنحة الداخلية للقصر مثالية."],"spots":[["الرقعة","رقعة ويتشي على منضدة خلف الدرابزين."],["اللاعبة التي تضع حجرًا","امرأة بثوب بنفسجي فاتح تمد يدها إلى الرقعة."],["المتفرجات","نساء منحنيات على اللعب."],["السيدة ذات المروحة","امرأة تمسك مروحة مستديرة بين الأعمدة."],["حجر الزينة","صخرة زرقاء في حوض على شكل لوتس."],["الوصيفة حاملة الآلة","وصيفة تحمل على الأرجح آلة بيبا."]]},"homerbg":{"title":"الطاولة","artist":"وينسلو هومر","date":"نحو 1877","place":"الولايات المتحدة","game":"الطاولة (النرد)","medium":"حفر على مقطع الخشب","size":"","credit":"","p":["حفر على الخشب عن رسم للرسام الأمريكي وينسلو هومر (1836–1910)، الذي رسم في شبابه رسومًا كثيرة لمثل هذه المطبوعات. وفي الأسفل «396.—BACKGAMMON.—WINSLOW HOMER.»، فالأرجح أنها ورقة من سلسلة مرقّمة في كتاب أو مجلة.","تجلس امرأتان متقابلتين على أريكة مزخرفة وتلعبان الطاولة على رقعة موضوعة على حجريهما. وعلى الرقعة شيء أبيض مستدير لا يتضح ما هو. وقد حُفرت طيات التنانير الطويلة ومساند الأريكة الملتفة بخطوط دقيقة."],"spots":[["الرقعة","الرقعة على حجري المرأتين."],["المرأة على اليسار","شعرها مرفوع، تمد يدها إلى الرقعة."],["المرأة على اليمين","تميل إلى الأمام تتأمل الرقعة."],["مسند الأريكة","مسند على شكل لفّة."],["التنانير","تنانير طويلة بطيات دقيقة الخطوط."],["التعليق","«396.—BACKGAMMON.—WINSLOW HOMER.» في الأسفل."]]},"chessst":{"title":"رجل وامرأة يلعبان الشطرنج (صورة مجسّمة)","artist":"مجهول","date":"1852–1858","place":"غير معروف","game":"الشطرنج","medium":"صورة مجسّمة ملوّنة","size":"8.3 × 16.5 سم","credit":"","p":["زوج من الصور ملصق صورةً مجسّمة، يُعرف بالإنجليزية بعنوان «The Chess Players». حين يُنظر إليه بالمجسام تبدو الرقعة والقطع بارزة. وقد أُضيف اللون فوق الصورة بالأبيض والأسود، على الستارة الحمراء والثوب الأصفر.","المرأة ذات الثوب الأصفر تضع يدها على قطعة، والرجل المقابل، الظاهر من الخلف، يتأمل الرقعة. قطع حمراء وبيضاء في منتصف اللعب، لكن المشهد رُتّب على الأرجح في استوديو. وكانت مثل هذه الصور المجسّمة لمشاهد البيت تُباع على نطاق واسع في منتصف القرن التاسع عشر."],"spots":[["الرقعة والقطع","قطع حمراء وبيضاء على الرقعة المربعة."],["اليد التي تلعب","يد المرأة على قطعة."],["المرأة","بثوب أصفر وياقة بيضاء، منحنية على الرقعة."],["الرجل","جالس وظهره إلينا."],["الستارة الحمراء","الستارة الملوّنة في الخلف."],["الصورة الثانية","المنظر الأيمن؛ في المجسام يكتسب الزوج عمقًا."]]},"corrida":{"title":"لعبة نرد مصارعة الثيران (Corrida de Toros)","artist":"خوسيه غوادالوبي بوسادا","date":"1898","place":"المكسيك","game":"لعبة سباق بنردين على رهان","medium":"حفر ضوئي بارز على ورق","size":"40.4 × 30.0 سم","credit":"","p":["لعبة سباق برسوم بوسادا، عنوانها «CORRIDA DE TOROS» (مصارعة الثيران). تلتف الخانات حلزونيًا وتعرض بالترتيب حركات المصارعة ولحظاتها، من الخانة 1 في الخارج نحو المركز. وفي الوسط حلبة، وفي الأسفل اسم مطبعة أنطونيو فانيغاس أرويو.","بحسب «الشرح» في الأسفل، يضع لاعبان أو أكثر رهانهم ويتقدمون برمي نردين. الخمسة، «القفز بالعصا»، تنقل إلى 10؛ والاثنا عشر، «نطح البيكادور»، تدفع وتفوّت أدوارًا؛ والـ28، «تمريرة الصدر»، تعيد إلى البداية. ومن يبلغ 32، «جرّ الثور»، يأخذ كل الرهانات."],"spots":[["العنوان","كلمات «CORRIDA DE TOROS»."],["الحلبة","مبنى الحلبة في قلب الحلزون."],["الخانة 1","البداية عند مدخل الحلزون."],["رأس الثور","رأس ثور بقرنين أعلى اليمين."],["المصارع","صورة مصارع ثيران أسفل اليسار."],["الشرح","«EXPLICACION» المطبوع في الأسفل."]]},"ambrocards":{"title":"ثلاثة رجال يلعبون الورق","artist":"صانع مجهول (أمريكي)","date":"1865","place":"الولايات المتحدة","game":"الورق","medium":"أمبروتايب","size":"14.0 × 11.0 سم","credit":"","p":["الأمبروتايب سالبٌ رقيق على زجاج يُبطَّن من خلفه بالأسود فيبدو موجبًا. كان أرخص من الداغيروتايب، فانتشر في أمريكا في خمسينيات القرن التاسع عشر وستينياته. وهذه الصورة خلف إطار مذهّب في علبة مبطنة بمخمل أحمر.","أمام خلفية سادة يجلس ثلاثة رجال حول منضدة صغيرة وفي أيديهم الأوراق. الأيسر يعتمر قبعة مستديرة والأيمن قبعة ذات حافة أمامية، وكلاهما يضع سيجارًا في فمه؛ والرجل في الوسط بسترة داكنة ينظر إلينا. والأرجح أنهم اتخذوا وضعية من هو في منتصف اللعب من أجل الكاميرا."],"spots":[["الأيدي","أيدٍ تمسك الأوراق فوق المنضدة."],["ذو القبعة المستديرة","إلى اليسار ومعه سيجار."],["الرجل في الوسط","بسترة داكنة ينظر إلينا."],["ذو القبعة الأمامية","إلى اليمين ومعه سيجار."],["الإطار المذهّب","الإطار الذهبي المنقوش حول الصورة."],["العلبة","العلبة المبطنة بالمخمل الأحمر."]]},"morphy":{"title":"بول مورفي، بطل الشطرنج","artist":"وينسلو هومر","date":"1859","place":"الولايات المتحدة","game":"الشطرنج","medium":"حفر على مقطع الخشب","size":"","credit":"","p":["صورة شخصية محفورة على الخشب كُتب تحتها «PAUL MORPHY, THE CHESS CHAMPION»، عن رسم لوينسلو هومر (1836–1910) حين كان رسامًا شابًا. وكان مورفي (1837–1884) من نيو أورلينز، جاب أوروبا في 1858–1859 وهزم كبار اللاعبين واحدًا بعد آخر، وعاد مشهورًا.","يجلس مورفي الشاب واضعًا يده اليسرى على حافة رقعة، بجانب ملك ورخ وبيادق وقطع أخرى. صُنعت سنة 1859 حين عاد نجمًا، والأرجح أنها طُبعت رسمًا توضيحيًا في صحيفة أو مجلة."],"spots":[["القطع","ملك ورخ وبيادق وغيرها على الرقعة."],["اليد على الرقعة","يده اليسرى على حافة الرقعة."],["وجه مورفي","البطل الذي تجاوز العشرين بقليل."],["ربطة العنق","ياقة أنيقة."],["اليد على الركبة","يده اليمنى على ركبته."],["العنوان","«PAUL MORPHY, THE CHESS CHAMPION» في الأسفل."]]},"dutton":{"title":"عائلة داتون في صالون شيربورن بارك، غلوسترشير","artist":"يوهان زوفاني","date":"نحو 1772","place":"إنجلترا","game":"الورق","medium":"زيت على قماش","size":"101.5 × 127.0 سم","credit":"","p":["من أعمال يوهان زوفاني (1733–1810)، الرسام المولود في ألمانيا الذي صنع مجده في إنجلترا. نشأت «لوحة المحادثة» التي تصوّر الأسرة في جلسة غير رسمية في إنجلترا في القرن الثامن عشر وراجت كثيرًا. والمشهد في صالون شيربورن بارك في غلوسترشير.","بحسب المتحف، يفكّر الأب وابنته والأم وابنها في الحركة التالية في لعبة ورق. كانت الأسرة قد فقدت عزيزًا للتو، فارتدى الوالدان حدادًا كاملًا بالأسود، والأبناء نصف حداد بالبنفسجي الفاتح والأبيض والرمادي."],"spots":[["مائدة اللعب","مائدة مكسوة بالجوخ الأخضر وعليها أوراق."],["الأب","بالأسود، يمسك أوراقه."],["الابنة","بالأبيض، تتأمل أوراقها."],["الابن","بالرمادي، يمسك أوراقه."],["الأم","بثوب حداد أسود."],["المدفأة","مدفأة رخامية تشتعل فيها النار."]]},"whist":{"title":"أكاديميو عيد الميلاد: لعبة ويست مشتركة","artist":"جيمس بريذرتون (على الأرجح عن رسم هـ. و. بنبري)","date":"1773","place":"إنجلترا","game":"الويست (ورق اللعب)","medium":"حفر بالحمض","size":"26.5 × 39.6 سم","credit":"","p":["بحسب المتحف، هي هجاء لأكاديميي كامبريدج. في أسفل اليسار يبدو أنه يُقرأ «H. W. Bunbury del. 1772» وفي أسفل اليمين «J. Bretherton f.»، ونُشرت سنة 1773 من متجر في شارع نيو بوند بلندن. وعلى الجدار قبعات أكاديمية معلّقة.","أربعة سادة يلعبون الويست بالورق وهم يتبادلون التكشير. يُلعب الويست بزوجين من الشركاء، فـ«اللعبة المشتركة» في العنوان تورية على الأرجح. وفي الخلف رجل يرفع أصابعه فوق رأس آخر ساخرًا. وبالقرب خادمان وكلبان."],"spots":[["الأوراق على المائدة","أوراق مُلعبة على المائدة."],["الأكاديمي ذو الشعر المستعار","عالم بشعر مستعار كبير يضم أوراقه إلى صدره."],["إشارة الأصابع","رجل في الخلف يرفع أصابعه فوق رأس آخر."],["الخادمة","خادمة بقبعة تحمل صينية."],["القبعات الأكاديمية","قبعات جامعية معلّقة على الجدار."],["الكلب الأيمن","كلب صغير ينبح أسفل اليمين."]]},"hey":{"title":"ثلاثة رجال يلعبون الشطرنج","artist":"باول هاي","date":"1877–1952","place":"ألمانيا","game":"الشطرنج","medium":"طبعة (على الأرجح حفر بالحمض)","size":"19.3 × 26.0 سم","credit":"","p":["طبعة للرسام والمصوّر الألماني باول هاي (1867–1952). ثلاثة رجال مسنّين ينحنون على رقعة شطرنج واحدة، وخطوط دقيقة متراكبة ترسم تجاعيدهم العميقة ولحاهم البيضاء.","كما يذكر سجل المتحف، يسند الرجل الأيسر ذقنه بيده، ويمسك الأيمن سيجارًا وهو يمد يده فوق القطع. وعلى يسار المائدة فنجانا قهوة وكأس وعلبة كبريت. والأرجح أنها مباراة في مقهى."],"spots":[["رقعة الشطرنج","الرقعة والقطع على المائدة."],["المسند ذقنه","أبيض اللحية غارق في التفكير."],["الرجل الأوسط","منحنٍ يمد يده إلى قطعة."],["الرجل الأيمن","يطل من الخلف."],["اليد ذات السيجار","سيجار بين الأصابع."],["القهوة والكبريت","فنجانان وكأس وعلبة كبريت على اليسار."]]},"artful":{"title":"الورقة الماكرة، أو ورقة زائدة على الجدة. القلوب هي الحكم!","artist":"مجهول","date":"1852–1863","place":"على الأرجح بريطانيا","game":"الورق","medium":"صورة مجسّمة ملوّنة","size":"8.4 × 17.4 سم","credit":"","p":["العنوان الإنجليزي «The artful card, or, one too many for granny. Hearts are trumps!». مشهد هزلي صغير عن التغلب على الجدة بورقة ماكرة، صُنع زوجًا من الصور المجسّمة. ومن العنوان الإنجليزي يُرجّح أنه صُنع في بريطانيا.","إلى مائدة مستديرة تلعب الجدة وفتاة صغيرة الورق، بينما الشابة ذات الثوب الأخضر تمسك أوراقها ويحتضنها شاب من الخلف. و«القلوب هي الحكم» على الأرجح تورية بين لون الورق والحب. والغرفة بمغزلها وخزانة الأواني هي بلا شك ديكور استوديو."],"spots":[["أوراق الشابة","الأوراق التي تمسكها الشابة ذات الثوب الأخضر."],["الشاب","يده على كتفها من الخلف."],["الجدة","امرأة مسنة بمنديل، عيناها على أوراقها."],["الفتاة","تبتسم وهي تلعب ورقة."],["المائدة","مائدة مستديرة عليها أوراق وأشياء صغيرة."],["خزانة الأواني","خزانة بزجاج فيها أوانٍ."]]},"cezcards":{"title":"دراسة للاعبي الورق","artist":"بول سيزان","date":"1890–1892","place":"فرنسا","game":"الورق","medium":"ألوان مائية مع غرافيت على ورق بيج","size":"36.2 × 48.5 سم","credit":"","p":["في تسعينيات القرن التاسع عشر، في إكس جنوب فرنسا، رسم سيزان عدة لوحات لرجال يلعبون الورق. وهذه دراسة بالألوان المائية لتلك السلسلة: رجل بقبعة وشارب يجلس إلى مائدة وينظر في أوراقه.","فوق خطوط الغرافيت تلتقط غسلات رقيقة من الأزرق والرمادي ثنيات السترة وثقل الجسد. وتُرك الجانب الأيمن وطرف المائدة غير مكتملين، فاللون لا يحيط إلا بالشخص. ويقال إن نماذجه كانوا من العاملين في تلك الناحية."],"spots":[["الوجه","مطرق العينين تحت القبعة ينظر في أوراقه."],["الأوراق","أوراق يمسكها بكلتا يديه."],["المائدة","مائدة مرسومة بالقلم فقط."],["الكرسي","ظهر الكرسي إلى اليسار."],["السترة","ثنيات مبنية بالأزرق والرمادي."],["الجزء غير المكتمل","قرب أرجل المائدة لم يبق إلا الخطوط."]]},"vuillardck":{"title":"دور الضامة، من «مناظر ودواخل»","artist":"إدوار فويار","date":"1899","place":"فرنسا","game":"الضامة","medium":"طباعة حجرية ملوّنة على ورق صيني عاجي رمادي","size":"36.9 × 28.5 سم","credit":"","p":["اللوحة الأولى من «مناظر ودواخل»، مجموعة طبعات حجرية ملوّنة للرسام الفرنسي فويار، نشرها تاجر الفن أمبرواز فولار وطبعها الطبّاع أوغست كلو.","في غرفة تغمرها ورق الجدران المزخرف يجلس رجل ملتحٍ أمام رقعة ضامة، وامرأة بفستان مربعات واقفة تضع يدها على ذقنها وتنظر. تذوب الأشخاص والجدران والأريكة في ألوان مسطحة وزخارف، ولا يبرز بوضوح إلا مربعات الرقعة السوداء والبيضاء."],"spots":[["الرقعة","رقعة الضامة السوداء والبيضاء."],["الرجل الملتحي","جالس أمام الرقعة."],["المرأة الواقفة","بفستان مربعات ويدها على ذقنها."],["ورق الجدران","ورق مملوء بخطوط ملتفة."],["الوسادة المزهّرة","قماش مزخرف أسفل اليسار."],["المصباح","شكل مصباح نحيل عند الجدار."]]},"cruikchess":{"title":"دور شطرنج","artist":"جورج كروكشانك عن رسم النقيب فريدريك ماريات","date":"1814","place":"إنجلترا","game":"الشطرنج","medium":"حفر بالحمض ملوّن يدويًا","size":"23.8 × 34.5 سم","credit":"","p":["طبعة لرسام الكاريكاتير الإنجليزي كروكشانك عن مسودة لماريات، الضابط البحري الذي صار روائيًا، نشرتها في لندن هانا همفري. وفي الأسفل عنوان «GAME of CHESS».","إلى مائدة عليها شموع يتقابل سيدان مسنّان أمام رقعة الشطرنج. خلف كل منهما متفرج: الأيسر يضع إصبعه على شفتيه طالبًا الصمت، والأيمن يتفحص الرقعة بنظارة ذات مقبض. والأرجح أنها سخرية من المتفرجين الذين لا يكفّون عن التدخل."],"spots":[["الرقعة","رقعة الشطرنج بقطعها البيضاء والسوداء."],["الشموع","شمعتان تضيئان الرقعة."],["طالب الصمت","متفرج يضع إصبعه على شفتيه."],["صاحب النظارة","متفرج يتفحص الرقعة بنظارته."],["الكلب النائم","كلب نائم تحت المائدة."],["العنوان","«GAME of CHESS» في الأسفل."]]},"domino98":{"title":"امرأة وطفلة تلعبان الدومينو إلى مائدة","artist":"فنان مجهول (أمريكي)","date":"نحو 1898","place":"الولايات المتحدة","game":"الدومينو","medium":"طبعة ألبومين ملصقة على زجاج","size":"40.8 × 51.1 سم","credit":"","p":["صورة كبيرة، على الأرجح من استوديو أمريكي، أُتمّت بلصقها على زجاج. امرأة بثوب أبيض وطفلة مجعّدة الشعر تجلسان على جانبي مائدة صغيرة مزينة بالزهور.","على المائدة قطع دومينو، والمرأة تضع قطعة. والطفلة تسند ذقنها بيدها وتنظر. والستائر والخزانة المزخرفة واللوحات على الجدار على الأرجح خلفية استوديو."],"spots":[["قطع الدومينو","قطع دومينو بيضاء على المائدة."],["الطفلة","تسند ذقنها وتنظر إلى القطع."],["المرأة","بثوب أبيض تضع قطعة."],["الزهور","مزهرية على المائدة."],["الخزانة","خزانة مزخرفة في الخلف إلى اليمين."],["الكتابة","حروف بيضاء أسفل اليمين."]]},"langkat":{"title":"ألبرت غلازر يلعب الورق مع صديقين على قارب، لانغكات، سومطرة","artist":"مجهول (هـ. إرنست وشركاه)","date":"1895–1905","place":"إندونيسيا (لانغكات، سومطرة)","game":"الورق","medium":"صورة فوتوغرافية","size":"17.5 × 22.8 سم","credit":"","p":["صورة التُقطت في لانغكات شمال سومطرة. في أسفلها إلى اليمين ختم بارز للاستوديو «H. Ernst & Co. / Bindjey Langkat»، وعلى ظهرها ملاحظة بخط اليد تقول إن الرجل في الوسط هو ألبرت غلازر، أخو إحدى السيدات.","على سطح قارب تحت مظلة، يجلس ثلاثة رجال بثياب بيضاء إلى طاولة والورق في أيديهم. على الطاولة أوراق وقطع صغيرة تشبه النقود، وبجانب الرجل الأيمن زجاجة. وتحكي الثياب البيضاء والمظلة عن الحياة في مناخ حار."],"spots":[["على الطاولة","أوراق موزعة وقطع تشبه النقود."],["غلازر","الرجل في الوسط يفرد أوراقه؛ والملاحظة على الظهر تسمّيه."],["الرجل الأيسر","يظهر نصفه من الخلف، والورق في يده."],["الرجل الأيمن","بشارب، والورق في يده."],["الزجاجة","زجاجة بجانب الرجل الأيمن."],["المظلة","زينة من أوراق تتدلى من المظلة."]]},"chatur":{"title":"دور في الشاترانجا","artist":"مجهول","date":"1805–1815","place":"الهند","game":"الشاترانجا","medium":"غواش وذهب، فرشاة","size":"16.2 × 9.8 سم (الصورة)","credit":"","p":["منمنمة هندية. بحسب سجل المتحف، تلعب امرأتان الشاترانجا، وهي لعبة رقعة، بينما تحمل خادمة منشّة ذباب. والشاترانجا لعبة هندية قديمة تُعدّ سلف الشطرنج.","تحت أقواس بيضاء، على بساط أحمر، تتقابل امرأة بثوب أزرق داكن وأخرى بثوب برتقالي أمام رقعة مربعات. والمرأة ذات الثوب البرتقالي تمد يدها كأنها تتكلم. ويحيط بالصورة إطار أحمر داكن محدد بخطوط سوداء وبيضاء."],"spots":[["الرقعة","رقعة مربعات على البساط الأحمر."],["ذات الثوب الأزرق","متحلية بالذهب، تمد يدها إلى الرقعة."],["ذات الثوب البرتقالي","قبالتها، ويدها ممدودة."],["الخادمة","واقفة في الخلف."],["منشّة الذباب","ترفعها الخادمة."],["الإطار الأحمر","إطار أحمر داكن بخطوط سوداء وبيضاء."]]},"shabbarat":{"title":"مساء في جناح النساء","artist":"مجهول","date":"1760–1770","place":"الهند","game":"الشوبار (البتشيسي)","medium":"غواش وذهب، فرشاة","size":"34.3 × 25.6 سم","credit":"","p":["منمنمة هندية. بحسب سجل المتحف، تلعب أربع نساء لعبة رقعة في فناء قصر واسع، وهي اللعبة المسماة شوبار أو بتشيسي. ويجلسن حول رقعة من القماش على شكل صليب.","المرأة في المقدمة يمينًا تمسك ثلاثة نرود مستطيلة مستعدة للرمي. وبجانبها، متكئة على وسادة، أعلى السيدات منزلة. الوقت ليل، لكن المصابيح تضيء الشرفة في كل مكان، وأضواء لا تُحصى تصطف على أسوار المدينة البعيدة. ويرجّح السجل أنهم يحتفلون بليلة البراءة."],"spots":[["الرقعة الصليبية","رقعة على شكل صليب مفروشة على الأرض."],["المرأة ذات النرد","في المقدمة، تمسك النرود المستطيلة."],["السيدة المتكئة","أعلى السيدات منزلة."],["الخادمة","تقترب بصينية."],["مصباح","شمعة تحت ناقوس زجاجي."],["الجوسق البعيد","حديقة بنافورة وجوسق وأضواء المدينة."]]},"govase":{"title":"مزهرية بيضاوية فيها نساء يلعبن الغو","artist":"مجهول (ختم «تانغ جينتانغ»)","date":"1724","place":"الصين (غوانغدونغ)","game":"الغو (الويتشي)","medium":"خزف بمينا فوق الطلاء وتذهيب","size":"الارتفاع 15.3 سم","credit":"","p":["مزهرية صينية من خزف رقيق جدًا مرسومة بالمينا. على ظهرها نقش: «صورة دور في الغو، رُسمت في يوم عيد الزهور من سنة جياتشن، في بيت مريح على نهر اللؤلؤ في لينغنان»، مع الختم الأحمر «تانغ جينتانغ». وكانت ضمن مجموعة خزف الجامع جان تيودور روايه في لاهاي.","امرأتان متقابلتان أمام رقعة غو على منضدة؛ اليسرى تمسك وعاء أحجار. وإلى اليمين امرأتان وطفلان ينحنون للمشاهدة. وعلى الحامل في الخلف تحف، منها مزهرية فيها ريش طاووس ومرجان."],"spots":[["الرقعة","رقعة غو على المنضدة بأحجار بيضاء وسوداء."],["اللاعبة اليسرى","تمسك وعاء الأحجار وتشير بإصبعها."],["اللاعبة اليمنى","منحنية على الرقعة."],["المتفرجات","نساء يتطلعن من الخلف."],["ريش الطاووس والمرجان","في مزهرية على الحامل."],["وعاء الأحجار","في يد المرأة اليسرى."]]},"yokihi":{"title":"رجل يلعب الطاولة مع سيدة (الإمبراطور شوان تسونغ ويانغ غويفي)","artist":"مجهول (سوريمونو)","date":"1822","place":"اليابان","game":"بان سوغوروكو (الطاولة اليابانية)","medium":"طباعة خشبية ملوّنة بأصباغ معدنية","size":"21.6 × 19.1 سم","credit":"","p":["سوريمونو: مطبوعة فاخرة تجمع الصورة والشعر، طُبعت على ورق سميك بمساحيق معدنية، وكان الشعراء يطلبونها هدايا لأصدقائهم. وعلى هذه قصيدة واسم الشاعر تاتشيبانا نو غوئن.","بحسب سجل المتحف، يلعب إمبراطور تانغ شوان تسونغ (685–762) السوغوروكو مع محظيته المفضلة يانغ غويفي (719–756)، وهي لعبة من أقارب الطاولة والتريكتراك. وعلى رقعة على هيئة صندوق فوق حامل أحمر قطع سوداء وبيضاء."],"spots":[["الرقعة","رقعة سوغوروكو على هيئة صندوق فوق حامل أحمر."],["يانغ غويفي","بزهور في شعرها، ويدها على الرقعة."],["شوان تسونغ","يده على ذقنه، ينظر إلى الرقعة."],["القصيدة","قصيدة واسم الشاعر أعلى اليسار."],["الستارة","ستارة مطوية مرسوم عليها جبال في الخلف."],["التوقيع والختم","توقيع وختم أحمر أسفل اليمين."]]},"disderi":{"title":"رجال بثياب البحارة يلعبون الورق","artist":"ديسديري وشركاه","date":"1850–1890","place":"فرنسا (باريس)","game":"الورق","medium":"طبعة ألبومين (بطاقة زيارة)","size":"8.6 × 5.3 سم","credit":"","p":["صورة بحجم بطاقة الزيارة من ألبوم، مطبوع على ظهرها «Disdéri & Cie، 8 جادة الإيطاليين، باريس». وديسديري هو المصوّر الذي نشر «بطاقة الزيارة»، أي صورًا صغيرة تُطبع بالجملة كبطاقات التعريف.","رجال بثياب قديمة الطراز — قبعات مثلثة ومعاطف طويلة وجوارب بيضاء — يلعبون الورق حول طاولة مزخرفة. يصف سجل المتحف الزي بأنه زي بحارة، لكنه على الأرجح زي مسرحي أو تنكري. والرجل في الوسط واقف يطل على الطاولة."],"spots":[["الطاولة","طاولة ذات حافة مزخرفة عليها أوراق وأكواب."],["الرجل الواقف","بقبعة مثلثة ينحني على الطاولة."],["الرجل الأيسر","جالس والورق في يده."],["الرجل الأيمن","بقبعة مثلثة والورق في يده."],["أحذية بأبازيم","جوارب بيضاء وأحذية بأبازيم."],["الإطار المذهّب","الحافة الذهبية للكرتون."]]},"gans":{"title":"لعبة الإوزة (حلزون من 74 خانة)","artist":"يان أورتمان (الأب)، عن تصميم دانيال فيليم ستوبندال","date":"1763–1823","place":"هولندا","game":"لعبة الإوزة (سباق بالنرد)","medium":"حفر على الخشب ملوّن بالأزرق والأحمر والأخضر","size":"40.8 × 46.8 سم","credit":"","p":["رقعة سباق حلزونية طُبعت في هولندا. بحسب المتحف تمتد الخانات من 1 إلى 74 وفي بعضها صور. حفر يان أورتمان القالب عن تصميم ستوبندال، الذي يظهر اسمه أسفل اليمين مع كلمة «invenit».","الهدف، الخانة 74، معبد على شاطئ البحر عند الغروب في الوسط. وفي الخانات كلمات مثل «LEER GELD» (ثمن التعلّم) و«DWAALWEG» (الطريق الضالّ) و«DOMHEID / WYSHEID» (الحماقة / الحكمة)، وهيكل عظمي بمنجل «EINDE» (النهاية)؛ والأرجح أنها لعبة أخلاقية عن طريق الحياة."],"spots":[["74: المعبد","الهدف: معبد على الشاطئ عند الغروب."],["1: البداية","الخانة الأولى أسفل اليسار."],["ثمن التعلّم","خانة «LEER GELD»، على الأرجح حيث يُدفع."],["الطريق الضالّ","درب في الغابة عليه «DWAALWEG»."],["النهاية","هيكل عظمي بمنجل: «EINDE»."],["النرد","خانة فيها نردان."]]},"merelle":{"title":"المريل والطائرة الورقية","artist":"كلودين ستيلا، عن جاك ستيلا","date":"1657","place":"فرنسا (باريس)","game":"المريل (لعبة الطاحونة)","medium":"حفر بالإزميل","size":"11.7 × 14.1 سم","credit":"","p":["اللوحة 17 من سلسلة ألعاب الأطفال التي حفرتها كلودين ستيلا عن رسوم عمّها الرسام جاك ستيلا. وبحسب المتحف هي من ألبوم يضم 51 حفرًا. واللاعبون أطفال عراة ممتلئون (بوتي).","في المقدمة يسارًا يلعبون المريل (لعبة الطاحونة) على رقعة محفورة في كتلة حجرية. وعلى الأرض يمينًا خطوط لعبة «فران دو كارو» التي تُرمى فيها النقود على المربعات، وأبعد يركض طفل بطائرة ورقية. وتقول الأبيات في الأسفل إن كلًّا يجتهد ليحسن اللعب."],"spots":[["رقعة المريل","رقعة محفورة في الحجر وعليها القطع."],["الطائرة الورقية","طائرة ورقية عالية في السماء."],["طفل الطائرة","يركض والخيط في يده."],["فران دو كارو","مربعات وأقطار مرسومة على الأرض."],["الطفل المشير","يحمل شيئًا ويشير إلى الخطوط."],["العنوان","«LA MERELLE, & LE CERF VOLANT»."]]},"feldcards":{"title":"لعب الورق إلى طاولة في الحديقة (صورة مجسّمة)","artist":"مجهول","date":"1850–1880","place":"غير معروف (ختم شركة من خرونينغن على الظهر)","game":"الورق","medium":"طبعة ألبومين (صورة مجسّمة)","size":"8.5 × 17.0 سم","credit":"","p":["صورة مجسّمة لأسرة أو جماعة أصدقاء يلعبون الورق إلى طاولة في حديقة، أمام تعريشة يكسوها اللبلاب. وعلى ظهرها ختم «Feldbrugge & Co.» من خرونينغن في هولندا، والأرجح أنه ختم المتجر أو الناشر الذي باعها.","الرجل الملتحي على اليسار يرفع ورقة عاليًا كأنه سيضرب بها الطاولة. ورجل يسند رأسه إلى يده، وصبي يمسك أوراقه، وشيخ أبيض الشعر، وامرأة تتفرج من الخلف يكملون اللحظة. ولأن الجميع كان عليهم الثبات طويلًا، فالأرجح أن المشهد مصطنع."],"spots":[["الورقة المرفوعة","الورقة التي يرفعها الملتحي."],["على الطاولة","أوراق لُعبت بالفعل."],["أوراق الصبي","أوراق الصبي الظاهر من الخلف."],["الشيخ","الرجل الأبيض الشعر الجالس يمينًا."],["المرأة المتفرجة","واقفة في الخلف تتابع اللعب."],["الكرسي المطرّز","كرسي في المقدمة مكسو بقماش مزهّر."]]},"tempel":{"title":"رقعة لعب «معبد الحظ»","artist":"مجهول","date":"1816","place":"هولندا","game":"لعبة سباق بالنرد","medium":"حفر على الخشب مع نص مطبوع بالحروف","size":"43.0 × 48.5 سم","credit":"","p":["ورقة لعب تلتف فيها الخانات من 1 إلى 74 حلزونيًا. في الوسط معبد مستدير على شاطئ البحر؛ وورقة القواعد المحفوظة في المجموعة نفسها تسميه «معبد الحظ» وتصف لعبة رمي، أي لعبة نرد.","معظم الخانات دوائر فارغة، لكن هنا وهناك ورود وأشواك ونرد وبوابة حديدية وعبّارة وصور أخرى، وكلمات مثل «LEER GELD» (أجرة التعلّم) و«DOMHEID» (الحماقة) و«WYSHEID» (الحكمة). والأرجح أنها لعبة وعظية تمر بالخير والشر في الطريق إلى المعبد."],"spots":[["معبد الحظ","المعبد على الشاطئ في الوسط: الخانة 74، الهدف."],["الخانة 1","البداية أسفل اليسار."],["أجرة التعلّم","خانة مكتوب فيها «LEER GELD»."],["النرد","حجرا نرد في الصف العلوي."],["العبّارة","صورة «OVER HAAL» (العبور) في الصف السفلي."],["الحماقة والحكمة","كلمتا «DOMHEID» و«WYSHEID» إلى اليمين."]]},"verkeer":{"title":"رقعة فيركير مصغّرة","artist":"مجهول","date":"1690–1710","place":"هولندا (أمستردام)","game":"فيركير (من أقارب الطاولة)، الشطرنج، لعبة الطاحونة","medium":"خشب جوز مطعّم بخشب الزيتون والأبنوس والبقس والعظم؛ تجهيزات نحاسية","size":"مغلقة 5.8 × 5.8 سم (مفتوحة 11.6 سم)","credit":"","p":["رقعة لعب لا يتجاوز ضلعها ستة سنتيمترات تُفتح كالعلبة. في الخارج رقعة شطرنج ورقعة طاحونة، وفي الداخل رقعة فيركير، قريبة الطاولة الهولندية. تُغلق بمفصلات نحاسية وخطّاف صغير.","وفي داخلها ما زال نرد واحد وتسع قطع من العظم وأربع من الأبنوس وثلاث قطع نقود صغيرة. ويدل رقمها في المتحف على أنها على الأرجح من أثاث بيت الدمى الخاص ببترونيلا أورتمان. ومع صغرها فإن تطعيمها متقن ومصنوعة كرقعة حقيقية."],"spots":[["النرد","نرد لا يزيد على حبة أرز."],["قطع العظم","قطع مستديرة من العظم الأبيض."],["قطع الأبنوس","قطع سوداء من الأبنوس."],["المثلثات","مثلثات مطعّمة بخشب فاتح وداكن."],["المفصلات","مفصلات نحاسية للطي."],["الخطّاف","خطّاف نحاسي صغير للإغلاق."]]},"silverbd":{"title":"رقعة لعب فضية مصغّرة مع قطعها","artist":"فريدريك فان سترانت الثاني","date":"1739","place":"هولندا (أمستردام)","game":"الضامة، لعبة الطاحونة","medium":"فضة","size":"5.4 × 5.4 سم","credit":"","p":["رقعة فضية لا يتجاوز ضلعها 5.4 سنتيمترات: 64 خانة وحافة مرفوعة وحلقة للتعليق. الخانات الداكنة محفورة بخطوط دقيقة، وعلى الوجه الآخر حُفرت خطوط لعبة الطاحونة.","عليها دمغة مدينة أمستردام وحرف السنة E الدال على 1739 ودمغة الصائغ فريدريك فان سترانت الثاني. وبقيت معها خمس عشرة قطعة ضامة، ثمانٍ مزينة بزهرة وسبع بدائرة. والأرجح أنها تحفة فضية مصغّرة لبيت دمى أو خزانة عرض."],"spots":[["قطع الزهرة","قطع مدموغة بزهرة."],["قطع الدائرة","قطع موسومة بدائرة."],["الحلقة","حلقة عند ركن الرقعة."],["الخانات المحفورة","خانات داكنة بخطوط دقيقة."],["الخانات الملساء","خانات فاتحة ملساء مصقولة."],["الحافة","الحافة المرفوعة حول الرقعة."]]},"schaak1550":{"title":"طقم شطرنج بقطع فرسان","artist":"مجهول","date":"1550","place":"ألمانيا","game":"الشطرنج","medium":"خشب البقس وخشب صنوبري","size":"أطول قطعة 10.5 سم","credit":"","p":["تقف كل قطعة على قاعدة مخروطة يحيط بها درابزين من الزهيرات، ونُحت فوقها فرسان وخيول. الملوك والملكات يركبون الخيل أو البغال كأنهم خارجون إلى الصيد.","بحسب سجل المتحف، يركب الملك الأسود حصانًا شاهقًا يطأ تنينًا، وفي عنقه سلسلة تذكّر بوسام الجزّة الذهبية، لعلها تشير إلى أنه شارل الخامس. وملكة تركب بغلًا جانبيًا وعلى يدها صقر. وفي أقصى اليمين قطعة هزلية: قرد يركب ظهر رجل."],"spots":[["الملك","ملك متوّج ملتحٍ على حصان."],["الملكة","ملكة تركب بغلًا جانبيًا ومعها صقر."],["قطعة القرد","قرد على ظهر رجل."],["قطعة هزلية","في أقصى اليسار رجل يركب آخر."],["المخلوقات تحت الحوافر","تنانين وحيوانات تحت الحوافر."],["القواعد","قواعد مخروطة بزهيرات."]]},"kraaij":{"title":"رجال ونساء يلعبون لعبة رقعة في غرفة المعيشة","artist":"مجهول","date":"1900–1910","place":"على الأرجح هولندا","game":"الطاولة (النرد)","medium":"طبعة كولوديون فضية تظهر بالطباعة المباشرة","size":"8.0 × 11.1 سم","credit":"","p":["صفحة من ألبوم عائلي يضم أيضًا صورًا لتجار النبيذ «كراي وشركاه، بوردو–أمستردام». في غرفة معيشة تتدلى فيها ثريا، يجلس رجال ونساء، لعلهم أهل وأصدقاء، حول طاولة.","على الطاولة رقعة على شكل صندوق قابل للطي مفتوح، وكل من المرأتين على الجانبين تمسك كوب نرد. يقول سجل المتحف «لعبة رقعة»، لكن الصندوق والكوبين يدلان على الأرجح على الطاولة (النرد). وفناجين القهوة قربهم وقفص العصفور في الخلف يوحيان بأمسية هادئة في البيت."],"spots":[["الرقعة الصندوق","صندوق قابل للطي فُتح رقعةً."],["الكوب الأيسر","كوب المرأة ذات النظارة."],["الكوب الأيمن","المرأة ذات الثوب المنقّط توشك أن ترمي."],["القفص","قفص عصفور على حامل في الخلف."],["الثريا","مصابيح بأغطية زجاجية معلقة من السقف."],["الرجل الواقف","إلى اليمين يتابع اللعب."]]},"braekel":{"title":"شيخ وعجوز يلعبان الضامة","artist":"فرديناند دو براكلير (الأب)","date":"1862","place":"بلجيكا (أنتويرب)","game":"الضامة","medium":"حفر بالحمض","size":"21.8 × 16.5 سم","credit":"","p":["حفر للرسام الأنتويرپي دو براكلير (1792–1883)، وعليه توقيع أسفل اليسار «Ferdinand De Braekeleer Antwerpen 1862». في مطبخ قديم بموقد يجلس شيخ وعجوز إلى مائدة صغيرة متقابلين.","على الرقعة قطع مستديرة؛ يلتقط الشيخ واحدة والعجوز تفتح يدها كأنها تردّ عليه. وعلى الأرض قبعة وقد سقطت بعض القطع أيضًا. وعلى الرف صحون، ومن النافذة تُرى البيوت."],"spots":[["الرقعة والقطع","الرقعة والقطع المستديرة على المائدة."],["الشيخ","منحنٍ يلتقط قطعة."],["العجوز","بغطاء رأس تتكلم وتشير بيدها."],["القبعة على الأرض","قبعة الشيخ موضوعة على الأرض."],["التوقيع","«Ferdinand De Braekeleer Antwerpen 1862»."],["الصحون","صحون كبيرة على الرف فوق الموقد."]]},"billiard":{"title":"البلياردو","artist":"عن رسم هـ. و. بنبري (الحفّار مجهول)","date":"1780","place":"إنجلترا (لندن)","game":"البلياردو","medium":"حفر بالحمض وتنقيط","size":"30.0 × 39.1 سم","credit":"","p":["طبعة عن رسم رسام الكاريكاتير الإنجليزي هنري ويليام بنبري، نشرها واتسون وديكنسون في لندن سنة 1780. وبحسب المتحف هي الرابعة في سلسلة.","رجلان يلعبان البلياردو والآخرون يتفرجون حابسين أنفاسهم. أحدهما ينحني على الطاولة ليضرب، وآخر يحمل عصاه على كتفه. وعلى الجدار حامل عصي وقرصان مستديران لعدّ النقاط. ويذكر المتحف أن الطاولة تبدو مثلثة."],"spots":[["الطاولة والكرات","الطاولة المكسوّة بالجوخ وكراتها."],["المصوّب","منحنٍ على الطاولة ليضرب."],["حامل العصا","ينتظر بعصاه الطويلة."],["قرصا العدّ","قرصان على الجدار، على الأرجح لعدّ النقاط."],["حامل العصي","صف من العصي على الجدار."],["الضاحكان","متفرجان على اليمين يضحكان معًا."]]},"baizi":{"title":"مئة طفل (تفصيل)","artist":"شو يانغهونغ","date":"القرن الثامن عشر","place":"الصين","game":"الويتشي (الغو)","medium":"لفافة أفقية؛ حبر (وألوان خفيفة) على ورق","size":"29.8 × 526 سم (اللفافة كاملة)","credit":"","p":["مشهد لعب الغو مقتطع من لفافة يزيد طولها على خمسة أمتار للرسام الصيني المحترف شو يانغهونغ. في حديقة يلعب مئة طفل ويعزفون ويقرؤون ويكتبون. و«المئة طفل» موضوع مهم في الفن الآسيوي يرمز إلى كثرة الذرية وازدهار الأسرة.","واللفافة معروفة أيضًا بنسخة لاحقة رسمها المعلم الياباني تاني بونتشو، وهي في المتحف نفسه. بجانب أوراق الموز وحجر زينة يلتف الأطفال حول رقعة غو على حامل منخفض؛ اثنان يلعبان وبأيديهما أوعية الأحجار والآخرون يتطلعون."],"spots":[["الرقعة","رقعة غو على حامل منخفض بأحجارها."],["الطفل الذي يلعب","بسترة زرقاء ويده في وعاء الأحجار."],["اللاعب الآخر","بالأبيض، منحنٍ على الرقعة."],["يدان خلف الرأس","طفل يتفرج من الخلف."],["حجر الزينة","صخرة كبيرة مليئة بالثقوب."],["مروحة الريش","طفل على اليسار يمسك مروحة ريش."]]},"schenkcards":{"title":"امرأتان صينيتان تلعبان الورق","artist":"بيتر سخنك (الابن)","date":"1727–1775","place":"هولندا (الموضوع: الصين)","game":"الورق","medium":"حفر بالحمض","size":"16.5 × 26.2 سم","credit":"","p":["لوحة من الجزء الأول من «صينيون مبتكرون حديثًا»، ألبوم لشخوص ومناظر على الطريقة الصينية نشره الحفّار والناشر الأمستردامي بيتر سخنك الابن. وهي من «الشينوازري»، أي الولع بصين متخيَّلة الذي راج في أوروبا.","بحسب سجل المتحف، تلعب امرأتان صينيتان الورق في حديقة بينما تقبل امرأة من اليمين بصينية مملوءة. والأوراق على المائدة تشبه ورق اللعب الأوروبي. وعلى اليسار أرنب يستريح فوق حامل، وفي النهر مركب شراعي."],"spots":[["الأوراق","أوراق مبسوطة على المائدة تبدو أوروبية."],["المرأة اليسرى","الأوراق في يدها، تنظر إلى شريكتها."],["المرأة اليمنى","تضع ورقة على المائدة."],["حاملة الصينية","تحمل صينية مليئة بالطعام."],["الأرنب","يستريح على حامل إلى اليسار."],["المركب الشراعي","مركب في النهر."]]},"gosaucer":{"title":"صحن صغير فيه لاعبو الغو","artist":"مجهول","date":"1725–1735","place":"الصين","game":"الغو (الويتشي)","medium":"خزف بمينا فوق الطلاء وتذهيب","size":"القطر 16.4 سم","credit":"","p":["صحن صيني مرسوم بألوان المينا الناعمة المعروفة بـ«العائلة الوردية». وعلى قاعدته علامة قوامها فرشاة وصولجان رويي وقلم حبر داخل دائرة مزدوجة. وتصف سجلات المتحف الشخوص تارة برجل وامرأة يلعبان الغو، وتارة بثلاث نساء تلعب اثنتان منهن.","في غرفة رقعة غو على منضدة؛ لاعبان متقابلان يضعان الأحجار، وثالث يقف خلفهما يتفرج. على المنضدة أوعية أحجار صفراء، وفي الخلف حامل عليه مزهرية، وإلى اليمين جرة زرقاء كبيرة."],"spots":[["الرقعة","رقعة غو بأحجارها على المنضدة."],["اللاعب الأيسر","بثوب بنفسجي فاتح، متكئ على المنضدة."],["اللاعب الأيمن","بثوب وردي، يضع حجرًا."],["المتفرج","واقف في الخلف يشاهد."],["المزهرية","مزهرية على حامل."],["الجرة الزرقاء","جرة كبيرة إلى اليمين."]]}};
